window.KB_TOPICS = [{"id":"cnp_001","n":"长度和时间的测量","g":"初2","sm":"上","ch":"八上 第一章 机械运动 1.1","d":"认识长度和时间的国际单位，会用刻度尺测长度、用停表测时间，会读数（估读到分度值下一位），知道误差不是错误。","mc":["能进行长度、时间的单位换算","会正确使用刻度尺读数并估读","能区分误差与错误，知道多次测量取平均值可以减小误差"],"dq":{"q":"长度的国际单位是什么？","a":"米（m）"}},{"id":"cnp_002","n":"运动的描述","g":"初2","sm":"上","ch":"八上 第一章 机械运动 1.2","d":"知道机械运动；知道判断物体是运动还是静止要先选参照物，同一物体选不同参照物时运动情况可能不同。","mc":["能说出什么是机械运动","能根据参照物判断物体是运动还是静止","能举例说明运动和静止的相对性"],"dq":{"q":"坐在行驶的列车里的乘客，以哪个物体为参照物时，他是静止的？","a":"他坐的车厢"}},{"id":"cnp_003","n":"运动的快慢","g":"初2","sm":"上","ch":"八上 第一章 机械运动 1.3","d":"理解速度的意义和公式 v = s/t，知道单位 m/s 与 km/h 的换算，能区分匀速直线运动和变速运动，会用平均速度做简单计算。","mc":["能用 v = s/t 及其变形进行计算","能进行 m/s 与 km/h 的换算（1 m/s = 3.6 km/h）","知道平均速度要用总路程除以总时间"],"dq":{"q":"一辆汽车 2 h 行驶了 144 km，它的平均速度是多少？","a":"72 km/h"}},{"id":"cnp_004","n":"速度的测量","g":"初2","sm":"上","ch":"八上 第一章 机械运动 1.4","d":"会用刻度尺和停表（或传感器）测量物体运动的平均速度，知道实验原理是 v = s/t，能分析斜面上小车前后半程的速度变化。","mc":["能说出测平均速度的原理和器材","会根据测量数据计算各段的平均速度","知道小车沿斜面下滑时速度越来越大"],"dq":{"q":"测量小车沿斜面下滑的平均速度，实验原理是什么？","a":"v = s/t"}},{"id":"cnp_005","n":"声音的产生与传播","g":"初2","sm":"上","ch":"八上 第二章 声现象 2.1","d":"知道声音是由物体振动产生的，声音的传播需要介质，真空不能传声；知道声速与介质种类和温度有关，15 ℃ 空气中声速约 340 m/s。","mc":["能说出声音产生和传播的条件","知道真空不能传声","能比较声音在固体、液体、气体中传播的快慢"],"dq":{"q":"声音是怎样产生的？","a":"由物体振动产生"}},{"id":"cnp_006","n":"声音的特性","g":"初2","sm":"上","ch":"八上 第二章 声现象 2.2","d":"知道音调、响度、音色是声音的三个特性：音调与频率有关，响度与振幅和距离发声体远近有关，音色由发声体本身决定。","mc":["能区分音调、响度和音色","知道音调由频率决定，响度与振幅有关","知道人耳听觉的频率范围及超声、次声"],"dq":{"q":"“闻其声而知其人”，主要是根据声音的哪个特性？","a":"音色"}},{"id":"cnp_007","n":"声的利用","g":"初2","sm":"上","ch":"八上 第二章 声现象 2.3","d":"知道声可以传递信息，也可以传递能量，能举出回声定位、B 超、超声波清洗、碎石等实例。","mc":["能区分声传递信息与传递能量的实例","会用回声测距进行简单计算"],"dq":{"q":"医生用 B 超检查身体，利用了声的什么作用？","a":"传递信息"}},{"id":"cnp_008","n":"噪声的危害和控制","g":"初2","sm":"上","ch":"八上 第二章 声现象 2.4","d":"知道噪声的来源和危害，知道用分贝（dB）表示声音强弱的等级，知道在声源处、传播过程中、人耳处控制噪声的方法。","mc":["能说出控制噪声的三个途径并举例","知道分贝表示声音强弱的等级"],"dq":{"q":"声音的强弱等级用什么单位表示？","a":"分贝（dB）"}},{"id":"cnp_009","n":"跨学科实践：制作隔音房间模型","g":"初2","sm":"上","ch":"八上 第二章 声现象 2.5","d":"运用声的传播和噪声控制知识，选择材料、设计并制作隔音房间模型，比较不同材料的隔音效果。","mc":["能说出选择隔音材料要考虑的因素","能设计控制变量的比较方案"],"dq":{"q":"下列材料中，做隔音房间模型的内衬隔音效果较好的是哪一种？","a":"多孔的泡沫塑料"}},{"id":"cnp_010","n":"温度","g":"初2","sm":"上","ch":"八上 第三章 物态变化 3.1","d":"知道温度表示物体的冷热程度，知道摄氏温度的规定，了解液体温度计的原理（液体热胀冷缩），会正确使用温度计和体温计。","mc":["能说出摄氏温度的规定和常见温度值","会正确使用温度计测量并读数（含零下读数）","知道体温计的特点与使用注意"],"dq":{"q":"常用液体温度计是根据什么原理制成的？","a":"液体的热胀冷缩"}},{"id":"cnp_011","n":"熔化和凝固","g":"初2","sm":"上","ch":"八上 第三章 物态变化 3.2","d":"知道熔化和凝固的概念，知道晶体有熔点、非晶体没有，晶体熔化时吸热温度不变，能读熔化、凝固图像。","mc":["能区分熔化与凝固，说出吸热、放热","能区分晶体和非晶体","能从熔化图像读出熔点和熔化时间"],"dq":{"q":"物质从固态变成液态叫什么？","a":"熔化"}},{"id":"cnp_012","n":"汽化和液化","g":"初2","sm":"上","ch":"八上 第三章 物态变化 3.3","d":"知道汽化的两种方式（蒸发和沸腾）及其特点，知道影响蒸发快慢的因素、沸点与气压的关系，知道液化的两种方法；会探究水沸腾前后温度变化的特点。","mc":["能区分蒸发与沸腾","能说出影响蒸发快慢的三个因素","知道沸腾的条件和沸腾时温度不变"],"dq":{"q":"夏天从冰箱里拿出的饮料瓶外壁会“出汗”，这是什么物态变化？","a":"液化"}},{"id":"cnp_013","n":"升华和凝华","g":"初2","sm":"上","ch":"八上 第三章 物态变化 3.4","d":"知道升华和凝华，升华吸热、凝华放热；能用六种物态变化解释雪、霜、雾、露和水循环等现象。","mc":["能区分升华与凝华","能判断霜、雾、露、雪等现象对应的物态变化","能说出六种物态变化的吸放热"],"dq":{"q":"冬天窗玻璃内侧出现的冰花，是什么物态变化形成的？","a":"凝华"}},{"id":"cnp_014","n":"跨学科实践：探索厨房中的物态变化问题","g":"初2","sm":"上","ch":"八上 第三章 物态变化 3.5","d":"在厨房情境中观察和解释蒸、煮、冷冻、解冻等过程中的物态变化，提出节能、安全的改进办法。","mc":["能用物态变化解释厨房中的常见现象","能提出与物态变化有关的安全或节能建议"],"dq":{"q":"揭开蒸锅盖时，被锅里出来的水蒸气烫伤往往比被同温度的开水烫伤更严重，原因是什么？","a":"水蒸气液化时还要放出大量热"}},{"id":"cnp_015","n":"光的直线传播","g":"初2","sm":"上","ch":"八上 第四章 光现象 4.1","d":"知道光源，知道光在同种均匀介质中沿直线传播，能解释影子、小孔成像、日食月食；知道真空中光速约 3×10⁸ m/s。","mc":["能用光的直线传播解释影子、小孔成像等现象","知道光速大小，知道光年是长度单位"],"dq":{"q":"下列物体中属于光源的是哪一个？","a":"正在发光的萤火虫"}},{"id":"cnp_016","n":"光的反射","g":"初2","sm":"上","ch":"八上 第四章 光现象 4.2","d":"探究并了解光的反射定律：反射光线、入射光线和法线在同一平面内，反射光线和入射光线分居法线两侧，反射角等于入射角；知道镜面反射和漫反射，知道光路可逆。","mc":["能说出光的反射定律","会根据入射角求反射角（角都与法线相比）","能区分镜面反射和漫反射"],"dq":{"q":"入射光线与法线的夹角是 40°，反射角是多少？","a":"40°"}},{"id":"cnp_017","n":"平面镜成像","g":"初2","sm":"上","ch":"八上 第四章 光现象 4.3","d":"探究并了解平面镜成像的特点：像与物大小相等，像与物到镜面的距离相等，像与物的连线与镜面垂直，成的是虚像；知道平面镜的应用。","mc":["能说出平面镜成像的特点","能根据物距求像距、像与物的距离","知道探究中用玻璃板代替平面镜的原因"],"dq":{"q":"人站在平面镜前 2 m 处，人与镜中像的距离是多少？","a":"4 m"}},{"id":"cnp_018","n":"光的折射","g":"初2","sm":"上","ch":"八上 第四章 光现象 4.4","d":"通过实验了解光的折射现象及特点：光从空气斜射入水或玻璃中，折射角小于入射角；垂直入射时传播方向不变；能解释池水变浅、筷子“折断”等现象。","mc":["能说出光从空气斜射入水中时折射光线的偏折方向","能用光的折射解释常见现象","知道折射中光路可逆"],"dq":{"q":"光从空气斜射入水中时，折射角与入射角相比怎样？","a":"折射角小于入射角"}},{"id":"cnp_019","n":"光的色散","g":"初2","sm":"上","ch":"八上 第四章 光现象 4.5","d":"通过实验了解白光由多种色光组成，知道光的三原色是红、绿、蓝，了解不同色光混合现象；了解红外线和紫外线的应用。","mc":["知道太阳光经三棱镜分解成七种色光","能说出光的三原色","能举出红外线和紫外线的应用"],"dq":{"q":"光的三原色是哪三种？","a":"红、绿、蓝"}},{"id":"cnp_020","n":"透镜","g":"初2","sm":"上","ch":"八上 第五章 透镜及其应用 5.1","d":"认识凸透镜和凹透镜，知道主光轴、光心、焦点、焦距；了解凸透镜对光有会聚作用，凹透镜对光有发散作用，会画三条特殊光线。","mc":["能区分凸透镜和凹透镜","知道凸透镜的会聚作用、凹透镜的发散作用","会画平行于主光轴、过光心、过焦点的特殊光线"],"dq":{"q":"中间厚、边缘薄的透镜叫什么？","a":"凸透镜"}},{"id":"cnp_021","n":"生活中的透镜","g":"初2","sm":"上","ch":"八上 第五章 透镜及其应用 5.2","d":"了解照相机、投影仪、放大镜的成像特点，知道实像和虚像的区别。","mc":["能说出照相机、投影仪、放大镜所成像的性质","能区分实像和虚像"],"dq":{"q":"照相机成的是什么像？","a":"倒立、缩小的实像"}},{"id":"cnp_022","n":"凸透镜成像的规律","g":"初2","sm":"上","ch":"八上 第五章 透镜及其应用 5.3","d":"探究并了解凸透镜成像规律：u > 2f 成倒立缩小实像，f < u < 2f 成倒立放大实像，u < f 成正立放大虚像；成实像时物近像远像变大。","mc":["能根据物距与焦距的关系判断像的性质","知道成实像时“物近像远像变大”","能由成像情况推算焦距范围"],"dq":{"q":"凸透镜焦距 10 cm，蜡烛放在离透镜 30 cm 处，成什么像？","a":"倒立、缩小的实像"}},{"id":"cnp_023","n":"眼睛和眼镜","g":"初2","sm":"上","ch":"八上 第五章 透镜及其应用 5.4","d":"知道眼睛相当于照相机，晶状体相当于凸透镜，视网膜上成倒立、缩小的实像；知道近视眼、远视眼的成因和矫正方法。","mc":["能说出近视眼像成在视网膜前方、用凹透镜矫正","能说出远视眼像成在视网膜后方、用凸透镜矫正"],"dq":{"q":"近视眼应该配戴什么透镜矫正？","a":"凹透镜"}},{"id":"cnp_024","n":"跨学科实践：制作望远镜","g":"初2","sm":"上","ch":"八上 第五章 透镜及其应用 5.5","d":"了解开普勒望远镜由两个凸透镜组成，物镜成倒立、缩小的实像，目镜相当于放大镜；动手制作简易望远镜并调节。","mc":["知道望远镜物镜和目镜的作用","能根据透镜焦距选择物镜和目镜"],"dq":{"q":"由两个凸透镜组成的望远镜，靠近眼睛的透镜叫什么？","a":"目镜"}},{"id":"cnp_025","n":"质量","g":"初2","sm":"上","ch":"八上 第六章 质量与密度 6.1","d":"知道质量是物体所含物质的多少，是物体的属性，不随形状、状态、位置、温度改变；会用托盘天平测量质量。","mc":["能进行质量单位换算并估测常见物体质量","知道质量不随形状、状态、位置变化","会正确使用托盘天平（放平、归零、调平衡、左物右码）"],"dq":{"q":"一名中学生的质量大约是多少？","a":"50 kg"}},{"id":"cnp_026","n":"密度","g":"初2","sm":"上","ch":"八上 第六章 质量与密度 6.2","d":"理解密度是物质的一种特性，ρ = m/V，单位 kg/m³ 和 g/cm³（1 g/cm³ = 1×10³ kg/m³），能用公式进行计算。","mc":["能用 ρ = m/V 及变形计算","能进行 g/cm³ 与 kg/m³ 的换算","知道同种物质密度一般不随质量、体积变化"],"dq":{"q":"水的密度是 1.0×10³ kg/m³，它的物理意义是什么？","a":"1 m³ 的水质量是 1.0×10³ kg"}},{"id":"cnp_027","n":"测量液体和固体的密度","g":"初2","sm":"上","ch":"八上 第六章 质量与密度 6.3","d":"会用量筒测体积，会用天平和量筒测量固体和液体的密度，能分析实验步骤顺序对误差的影响。","mc":["会正确读量筒（视线与凹液面底部相平）","会用排水法测固体体积并算密度","能设计减小误差的液体密度测量步骤"],"dq":{"q":"用量筒测水的体积，读数时视线应怎样？","a":"与凹液面的底部相平"}},{"id":"cnp_028","n":"密度的应用","g":"初2","sm":"上","ch":"八上 第六章 质量与密度 6.4","d":"能利用密度鉴别物质、计算不便直接测量的质量或体积，解释水结冰体积变大、气体密度受温度影响等现象。","mc":["会用密度鉴别物质","会用 m = ρV、V = m/ρ 求不能直接测量的量","能解释水的反常膨胀等现象"],"dq":{"q":"一块冰的体积是 2 m³，冰的密度取 0.9×10³ kg/m³，它的质量是多少 kg？（只填数值）","a":"1800"}},{"id":"cnp_029","n":"力","g":"初2","sm":"下","ch":"八下 第七章 力 7.1","d":"知道力是物体对物体的作用，物体间力的作用是相互的；知道力可以改变物体的运动状态和形状；知道力的三要素，会画力的示意图，力的单位是牛顿（N）。","mc":["能说出力的作用效果","知道物体间力的作用是相互的","知道力的三要素并会画力的示意图"],"dq":{"q":"力的单位是什么？","a":"牛顿（N）"}},{"id":"cnp_030","n":"弹力","g":"初2","sm":"下","ch":"八下 第七章 力 7.2","d":"知道弹性和弹力，知道在弹性限度内弹簧伸长量与拉力成正比，会正确使用弹簧测力计测量力。","mc":["能说出弹力产生的条件","会正确使用并读取弹簧测力计","知道弹簧伸长量与拉力成正比（弹性限度内）"],"dq":{"q":"下列力中不属于弹力的是哪一个？","a":"地球对物体的吸引力"}},{"id":"cnp_031","n":"重力","g":"初2","sm":"下","ch":"八下 第七章 力 7.3","d":"知道重力是由于地球的吸引而使物体受到的力，方向竖直向下，作用点在重心；知道 G = mg，g 约为 9.8 N/kg（题中常取 10 N/kg）。","mc":["能用 G = mg 计算重力或质量","知道重力方向竖直向下并说出应用","能区分质量和重力"],"dq":{"q":"质量为 50 kg 的同学，受到的重力是多少 N？（g 取 10 N/kg，只填数值）","a":"500"}},{"id":"cnp_032","n":"牛顿第一定律","g":"初2","sm":"下","ch":"八下 第八章 运动和力 8.1","d":"通过阻力对物体运动影响的实验和科学推理认识牛顿第一定律；知道一切物体都有惯性，惯性只与质量有关，能用惯性解释生活现象。","mc":["能说出牛顿第一定律及其得出方法（实验 + 推理）","知道惯性大小只与质量有关","能用惯性解释急刹车、安全带等现象"],"dq":{"q":"一切物体在没有受到力的作用时，总保持什么状态？","a":"静止状态或匀速直线运动状态"}},{"id":"cnp_033","n":"二力平衡","g":"初2","sm":"下","ch":"八下 第八章 运动和力 8.2","d":"知道平衡状态和平衡力，知道二力平衡的条件：作用在同一物体上，大小相等、方向相反、作用在同一直线上；能区分平衡力与相互作用力。","mc":["能说出二力平衡的四个条件","能区分平衡力与相互作用力","会用二力平衡求未知力"],"dq":{"q":"静止在水平桌面上的书，受到的平衡力是哪一对？","a":"书受到的重力和桌面对书的支持力"}},{"id":"cnp_034","n":"摩擦力","g":"初2","sm":"下","ch":"八下 第八章 运动和力 8.3","d":"知道摩擦力，探究并了解滑动摩擦力大小与压力大小和接触面粗糙程度有关；知道增大和减小摩擦的方法。","mc":["能说出影响滑动摩擦力大小的两个因素","知道测滑动摩擦力要匀速直线拉动木块","能判断增大或减小摩擦的方法"],"dq":{"q":"滑动摩擦力的大小与下列哪个因素有关？","a":"接触面的粗糙程度"}},{"id":"cnp_035","n":"同一直线上二力的合成","g":"初2","sm":"下","ch":"八下 第八章 运动和力 8.4","d":"了解合力的概念，知道同一直线上方向相同的两个力的合力等于二力之和，方向相反时等于二力之差、方向与较大的力相同。","mc":["会求同一直线上同向两力的合力","会求同一直线上反向两力的合力并判断方向"],"dq":{"q":"同一直线上方向相同的 3 N 和 5 N 两个力，合力是多少？","a":"8 N"}},{"id":"cnp_036","n":"压强","g":"初2","sm":"下","ch":"八下 第九章 压强 9.1","d":"理解压强 p = F/S，单位帕斯卡（Pa），知道增大和减小压强的方法；会计算固体压强。","mc":["能用 p = F/S 计算并统一单位（面积用 m²）","能判断增大或减小压强的方法","知道压力作用效果与压力和受力面积有关"],"dq":{"q":"压强的单位是什么？","a":"帕斯卡（Pa）"}},{"id":"cnp_037","n":"液体的压强","g":"初2","sm":"下","ch":"八下 第九章 压强 9.2","d":"知道液体内部向各个方向都有压强；探究并了解液体压强与深度和液体密度有关，p = ρgh；了解连通器及其应用。","mc":["知道液体压强随深度增加而增大，与液体密度有关","会用 p = ρgh 计算（h 是到自由液面的竖直距离）","能举出连通器的应用"],"dq":{"q":"水深 2 m 处，水产生的压强是多少 Pa？（ρ水 = 1.0×10³ kg/m³，g 取 10 N/kg，只填数值）","a":"20000"}},{"id":"cnp_038","n":"大气压强","g":"初2","sm":"下","ch":"八下 第九章 压强 9.3","d":"知道大气压强的存在，了解托里拆利实验和标准大气压（约 1.013×10⁵ Pa，相当于 760 mm 水银柱），知道大气压随高度增加而减小及其与生活的关系。","mc":["能举例说明大气压的存在","知道标准大气压的数值","知道大气压随海拔升高而减小"],"dq":{"q":"首先证明大气压存在的著名实验是什么？","a":"马德堡半球实验"}},{"id":"cnp_039","n":"跨学科实践：制作简易活塞式抽水机","g":"初2","sm":"下","ch":"八下 第九章 压强 9.4","d":"了解活塞式抽水机利用大气压把水抽上来的原理，动手制作简易抽水机，知道它能把水抽高的高度受大气压限制。","mc":["能说出活塞式抽水机的工作原理","知道在 1 个标准大气压下抽水高度约为 10 m"],"dq":{"q":"活塞式抽水机是利用什么把水抽上来的？","a":"大气压"}},{"id":"cnp_040","n":"流体压强与流速的关系","g":"初2","sm":"下","ch":"八下 第九章 压强 9.5","d":"知道流体在流速大的地方压强小、流速小的地方压强大，能解释飞机升力、站台安全线等现象。","mc":["能说出流体压强与流速的关系","能用它解释飞机升力和安全线等现象"],"dq":{"q":"流体中流速越大的位置，压强怎样？","a":"越小"}},{"id":"cnp_041","n":"浮力","g":"初2","sm":"下","ch":"八下 第十章 浮力 10.1","d":"知道浮力的方向竖直向上，浮力产生的原因是液体对物体上下表面的压力差；会用称重法测浮力；探究并了解浮力大小与排开液体的体积和液体密度有关。","mc":["会用称重法 F浮 = G - F示 求浮力","知道浮力方向竖直向上","知道浮力大小与 V排 和 ρ液 有关，与浸没深度无关"],"dq":{"q":"浮力的方向是怎样的？","a":"竖直向上"}},{"id":"cnp_042","n":"阿基米德原理","g":"初2","sm":"下","ch":"八下 第十章 浮力 10.2","d":"知道阿基米德原理：浸在液体中的物体受到向上的浮力，大小等于它排开液体所受的重力，F浮 = G排 = ρ液 g V排。","mc":["能说出阿基米德原理","会用 F浮 = ρ液 g V排 计算","知道 V排 与物体体积的关系（浸没时相等）"],"dq":{"q":"根据阿基米德原理，物体受到的浮力大小等于什么？","a":"它排开的液体所受的重力"}},{"id":"cnp_043","n":"物体的浮沉条件及应用","g":"初2","sm":"下","ch":"八下 第十章 浮力 10.3","d":"知道物体的浮沉条件（比较 F浮 与 G，或 ρ物 与 ρ液），知道漂浮时 F浮 = G，了解轮船、潜水艇、气球、密度计的原理。","mc":["能用浮力与重力或密度比较判断浮沉","知道漂浮、悬浮时 F浮 = G","能说出潜水艇靠改变自身重力实现浮沉"],"dq":{"q":"实心物体的密度小于液体密度时，放入液体中最终会怎样？","a":"漂浮"}},{"id":"cnp_044","n":"跨学科实践：制作微型密度计","g":"初2","sm":"下","ch":"八下 第十章 浮力 10.4","d":"利用漂浮条件制作简易密度计，知道密度计在不同液体中受到的浮力相等，液体密度越大，浸入越浅，刻度上小下大。","mc":["知道密度计利用漂浮时 F浮 = G 的原理","能判断密度计刻度的分布特点"],"dq":{"q":"同一支密度计放在不同液体中都漂浮，它受到的浮力有什么关系？","a":"相等"}},{"id":"cnp_045","n":"功","g":"初2","sm":"下","ch":"八下 第十一章 功和机械能 11.1","d":"知道做功的两个必要因素（作用在物体上的力、物体在力的方向上移动的距离），会用 W = Fs 计算，单位焦耳（J）。","mc":["能判断力是否对物体做功","会用 W = Fs 计算功"],"dq":{"q":"下列情况中，人对物体做了功的是哪一个？","a":"把箱子从地面搬到桌上"}},{"id":"cnp_046","n":"功率","g":"初2","sm":"下","ch":"八下 第十一章 功和机械能 11.2","d":"知道功率表示做功的快慢，P = W/t，单位瓦特（W）；能推导并使用 P = Fv。","mc":["会用 P = W/t 计算功率","能区分功和功率","会用 P = Fv 进行简单计算"],"dq":{"q":"功率是表示什么的物理量？","a":"做功快慢"}},{"id":"cnp_047","n":"动能和势能","g":"初2","sm":"下","ch":"八下 第十一章 功和机械能 11.3","d":"知道动能、重力势能、弹性势能；知道动能与质量和速度有关，重力势能与质量和高度有关，弹性势能与弹性形变程度有关。","mc":["能说出影响动能、重力势能大小的因素","能用控制变量法分析探究动能大小的实验"],"dq":{"q":"动能的大小与哪些因素有关？","a":"质量和速度"}},{"id":"cnp_048","n":"机械能及其转化","g":"初2","sm":"下","ch":"八下 第十一章 功和机械能 11.4","d":"知道机械能是动能和势能的总和，能分析动能和势能的相互转化，知道只有动能和势能相互转化时机械能守恒。","mc":["能分析滚摆、单摆、人造卫星等过程中的能量转化","知道不计空气阻力时机械能守恒"],"dq":{"q":"苹果从树上加速下落，能量是怎样转化的？","a":"重力势能转化为动能"}},{"id":"cnp_049","n":"杠杆","g":"初2","sm":"下","ch":"八下 第十二章 简单机械 12.1","d":"知道杠杆的五要素，会画力臂；探究并了解杠杆的平衡条件 F₁l₁ = F₂l₂；能区分省力杠杆、费力杠杆和等臂杠杆。","mc":["会找支点、画力臂（支点到力的作用线的距离）","会用 F₁l₁ = F₂l₂ 计算","能判断省力杠杆、费力杠杆"],"dq":{"q":"下列工具中属于费力杠杆的是哪一个？","a":"钓鱼竿"}},{"id":"cnp_050","n":"跨学科实践：制作简易杆秤","g":"初2","sm":"下","ch":"八下 第十二章 简单机械 12.2","d":"运用杠杆平衡条件设计并制作简易杆秤，确定定盘星（零刻度）和刻度，了解我国古代杆秤的智慧。","mc":["能用杠杆平衡条件说明杆秤的原理","知道杆秤的刻度是均匀的"],"dq":{"q":"杆秤是利用什么原理称量物体质量的？","a":"杠杆平衡条件"}},{"id":"cnp_051","n":"滑轮","g":"初2","sm":"下","ch":"八下 第十二章 简单机械 12.3","d":"知道定滑轮不省力但能改变力的方向，动滑轮能省一半力但费距离；会分析滑轮组的承重绳子段数，F = (G物 + G动)/n，s = nh。","mc":["能说出定滑轮、动滑轮的特点","会数滑轮组承担物重的绳子段数 n","会用 F = (G + G动)/n 和 s = nh 计算"],"dq":{"q":"旗杆顶部的滑轮是什么滑轮？它有什么作用？","a":"定滑轮，改变力的方向"}},{"id":"cnp_052","n":"机械效率","g":"初2","sm":"下","ch":"八下 第十二章 简单机械 12.4","d":"知道有用功、额外功、总功，知道机械效率 η = W有/W总，机械效率总小于 1；了解提高机械效率的方法。","mc":["能区分有用功、额外功和总功","会计算滑轮组、斜面的机械效率","能说出提高机械效率的方法"],"dq":{"q":"使用任何机械时，机械效率总是怎样？","a":"小于 1（100%）"}},{"id":"cnp_053","n":"热量 比热容","g":"初3","sm":"全","ch":"九全 第十三章 内能 13.1","d":"知道热量是热传递过程中传递内能的多少；通过实验了解比热容，会用 Q = cmΔt 计算吸收或放出的热量；能用水的比热容大解释生活现象。","mc":["会用 Q = cmΔt 计算","知道水的比热容是 4.2×10³ J/(kg·℃) 并能解释应用","知道比热容是物质的特性"],"dq":{"q":"质量为 2 kg 的水温度升高 10 ℃，吸收多少 J 的热量？（c水 = 4.2×10³ J/(kg·℃)，只填数值）","a":"84000"}},{"id":"cnp_054","n":"分子动理论的初步知识","g":"初3","sm":"全","ch":"九全 第十三章 内能 13.2","d":"知道物质由分子、原子构成；知道分子在不停地做无规则运动，温度越高运动越剧烈（扩散现象）；知道分子间存在引力和斥力，分子间有间隙。","mc":["能用扩散现象说明分子在运动","知道温度越高分子热运动越剧烈","知道分子间有引力和斥力"],"dq":{"q":"走进花园闻到花香，说明了什么？","a":"分子在不停地做无规则运动"}},{"id":"cnp_055","n":"内能","g":"初3","sm":"全","ch":"九全 第十三章 内能 13.3","d":"知道内能是物体内所有分子动能和分子势能的总和，一切物体都有内能；知道做功和热传递是改变内能的两种方式；能区分温度、热量和内能。","mc":["能说出改变内能的两种方式并举例","知道一切物体都有内能","能区分温度、热量、内能"],"dq":{"q":"冬天搓手取暖，是通过什么方式改变手的内能的？","a":"做功"}},{"id":"cnp_056","n":"能量的转化与守恒","g":"初3","sm":"全","ch":"九全 第十四章 内能的利用 14.1","d":"知道能量既不会凭空消灭，也不会凭空产生，只会从一种形式转化为其他形式或从一个物体转移到其他物体，总量保持不变；知道永动机不可能实现。","mc":["能说出能量守恒定律","能分析常见过程中的能量转化","能解释永动机为什么不可能实现"],"dq":{"q":"能量守恒定律指出，在能量转化和转移的过程中，能量的总量怎样？","a":"保持不变"}},{"id":"cnp_057","n":"热机","g":"初3","sm":"全","ch":"九全 第十四章 内能的利用 14.2","d":"了解热机是把内能转化为机械能的机器；知道汽油机四个冲程（吸气、压缩、做功、排气）及其能量转化。","mc":["能说出汽油机四个冲程的顺序","知道压缩冲程机械能转化为内能，做功冲程内能转化为机械能","能根据飞轮转速算做功次数"],"dq":{"q":"汽油机的哪个冲程把内能转化为机械能？","a":"做功冲程"}},{"id":"cnp_058","n":"热机的效率","g":"初3","sm":"全","ch":"九全 第十四章 内能的利用 14.3","d":"知道燃料的热值，会用 Q放 = mq 计算；知道热机效率是用来做有用功的能量与燃料完全燃烧放出能量之比，了解提高热机效率的途径。","mc":["会用 Q = mq 计算燃料放出的热量","知道热值是燃料的特性","会计算热机效率"],"dq":{"q":"完全燃烧 0.2 kg 汽油放出多少 J 的热量？（q汽油 = 4.6×10⁷ J/kg，只填数值）","a":"9200000"}},{"id":"cnp_059","n":"跨学科实践：制作简易热机模型","g":"初3","sm":"全","ch":"九全 第十四章 内能的利用 14.4","d":"利用内能做功的原理设计并制作简易热机模型（如蒸汽小船、热气流风车），分析其中的能量转化和提高效率的方法。","mc":["能说出简易热机模型中的能量转化","能提出提高模型效率的改进办法"],"dq":{"q":"试管中的水沸腾后，水蒸气把塞子冲出，这一过程相当于汽油机的哪个冲程？","a":"做功冲程"}},{"id":"cnp_060","n":"两种电荷","g":"初3","sm":"全","ch":"九全 第十五章 电流和电路 15.1","d":"知道摩擦起电和两种电荷，同种电荷相互排斥、异种电荷相互吸引；了解验电器、导体和绝缘体；知道原子由原子核和电子构成，摩擦起电是电子的转移。","mc":["知道电荷间的相互作用规律","知道摩擦起电的实质是电子转移","能区分常见的导体和绝缘体"],"dq":{"q":"电荷间的相互作用规律是什么？","a":"同种电荷相互排斥，异种电荷相互吸引"}},{"id":"cnp_061","n":"电流和电路","g":"初3","sm":"全","ch":"九全 第十五章 电流和电路 15.2","d":"知道电流的形成和方向（正电荷定向移动的方向），知道电路的组成（电源、用电器、开关、导线），会看、会画简单电路图，了解通路、断路、短路。","mc":["能说出电路的基本组成","知道电流方向的规定","能识别通路、断路和短路"],"dq":{"q":"物理学中规定的电流方向是什么？","a":"正电荷定向移动的方向"}},{"id":"cnp_062","n":"串联电路和并联电路","g":"初3","sm":"全","ch":"九全 第十五章 电流和电路 15.3","d":"知道串联电路和并联电路的连接特点，会连接简单的串联、并联电路，能说出生活中采用串联或并联的实例。","mc":["能根据电流路径判断串联和并联","知道串联电路中开关控制整个电路、并联电路干路开关控制全部","能举出家庭电路用电器并联等实例"],"dq":{"q":"家庭电路中的电灯、电视机、冰箱之间是怎样连接的？","a":"并联"}},{"id":"cnp_063","n":"电流的测量","g":"初3","sm":"全","ch":"九全 第十五章 电流和电路 15.4","d":"知道电流的单位安培（A）和毫安（mA），会使用电流表：串联在电路中，电流从“+”接线柱流入，选择合适的量程并正确读数。","mc":["会进行电流单位换算","知道电流表要串联、正进负出","会根据量程正确读数"],"dq":{"q":"电流表应怎样接入电路？","a":"串联在被测电路中"}},{"id":"cnp_064","n":"串、并联电路中电流的规律","g":"初3","sm":"全","ch":"九全 第十五章 电流和电路 15.5","d":"探究并了解串联电路中电流处处相等，并联电路中干路电流等于各支路电流之和。","mc":["知道串联电路电流处处相等","知道并联电路干路电流等于各支路电流之和","能用规律求未知电流"],"dq":{"q":"两只不同的灯泡串联，通过它们的电流有什么关系？","a":"相等"}},{"id":"cnp_065","n":"电压","g":"初3","sm":"全","ch":"九全 第十六章 电压·电阻 16.1","d":"知道电压是形成电流的原因，单位伏特（V），记住一节干电池 1.5 V、家庭电路 220 V；会使用电压表：并联在被测电路两端，正进负出。","mc":["知道常见电压值","知道电压表要并联","会进行电压单位换算"],"dq":{"q":"我国家庭电路的电压是多少？","a":"220 V"}},{"id":"cnp_066","n":"串、并联电路中电压的规律","g":"初3","sm":"全","ch":"九全 第十六章 电压·电阻 16.2","d":"探究并了解串联电路两端的总电压等于各部分电路两端电压之和，并联电路中各支路两端的电压相等且等于电源电压。","mc":["知道串联电路电压规律 U = U₁ + U₂","知道并联电路各支路电压相等","能用规律求未知电压"],"dq":{"q":"两个电阻串联在 6 V 的电源上，其中一个电阻两端的电压为 2 V，另一个电阻两端的电压是多少 V？（只填数值）","a":"4"}},{"id":"cnp_067","n":"电阻","g":"初3","sm":"全","ch":"九全 第十六章 电压·电阻 16.3","d":"知道电阻表示导体对电流的阻碍作用，单位欧姆（Ω）；知道导体的电阻与材料、长度、横截面积和温度有关，与电压、电流无关。","mc":["能说出影响电阻大小的因素","知道电阻是导体的性质，与电压电流无关","会进行电阻单位换算"],"dq":{"q":"导体的电阻与下列哪个因素无关？","a":"导体两端的电压"}},{"id":"cnp_068","n":"变阻器","g":"初3","sm":"全","ch":"九全 第十六章 电压·电阻 16.4","d":"知道滑动变阻器通过改变接入电路中电阻丝的长度来改变电阻，会正确连接（一上一下）并判断滑片移动时电阻的变化；了解其在电路中的作用。","mc":["知道滑动变阻器的原理","会“一上一下”连接并判断电阻变化","知道闭合开关前滑片应处于最大阻值处"],"dq":{"q":"滑动变阻器是通过改变什么来改变电阻的？","a":"接入电路中电阻丝的长度"}},{"id":"cnp_069","n":"跨学科实践：制作简易调光台灯","g":"初3","sm":"全","ch":"九全 第十六章 电压·电阻 16.5","d":"运用电路连接和变阻器知识设计并制作简易调光台灯，分析滑片位置与灯泡亮度的关系，注意用电安全。","mc":["能画出调光台灯的电路图（灯与变阻器串联）","能分析滑片移动时灯泡亮度变化"],"dq":{"q":"简易调光台灯中，灯泡和滑动变阻器应怎样连接？","a":"串联"}},{"id":"cnp_070","n":"电流与电压、电阻的关系","g":"初3","sm":"全","ch":"九全 第十七章 欧姆定律 17.1","d":"探究电流与电压、电阻的关系：电阻一定时电流与电压成正比，电压一定时电流与电阻成反比；会用控制变量法设计实验并分析数据。","mc":["知道电阻一定时 I 与 U 成正比","知道电压一定时 I 与 R 成反比","知道实验中滑动变阻器的作用"],"dq":{"q":"在电阻一定时，通过导体的电流与导体两端的电压是什么关系？","a":"成正比"}},{"id":"cnp_071","n":"欧姆定律","g":"初3","sm":"全","ch":"九全 第十七章 欧姆定律 17.2","d":"理解欧姆定律 I = U/R，会用它及变形式 U = IR、R = U/I 进行计算；知道 R = U/I 只是计算电阻的方法，电阻不由电压和电流决定。","mc":["会用 I = U/R 及其变形计算","知道公式中各量要对应同一导体同一时刻","理解 R = U/I 不表示电阻与电压成正比"],"dq":{"q":"一个 10 Ω 的电阻两端电压为 3 V，通过它的电流是多少 A？（只填数值）","a":"0.3"}},{"id":"cnp_072","n":"电阻的测量","g":"初3","sm":"全","ch":"九全 第十七章 欧姆定律 17.3","d":"会用伏安法（电流表和电压表）测量电阻：原理 R = U/I，能画电路图、连接电路、多次测量求平均值；知道小灯泡电阻随温度变化。","mc":["知道伏安法测电阻的原理和电路图","知道测定值电阻要多次测量取平均值","知道小灯泡电阻随温度升高而增大，不宜求平均"],"dq":{"q":"伏安法测电阻的原理是什么？","a":"R = U/I"}},{"id":"cnp_073","n":"欧姆定律在串、并联电路中的应用","g":"初3","sm":"全","ch":"九全 第十七章 欧姆定律 17.4","d":"能运用欧姆定律和串、并联电路的电流、电压规律进行计算；知道串联总电阻 R = R₁ + R₂，并联电路总电阻小于任一分电阻。","mc":["会求串联电路总电阻和电流","会用欧姆定律解并联电路问题","能分析滑片移动时电表示数的变化"],"dq":{"q":"5 Ω 和 10 Ω 的电阻串联，总电阻是多少 Ω？（只填数值）","a":"15"}},{"id":"cnp_074","n":"电能 电功","g":"初3","sm":"全","ch":"九全 第十八章 电功率 18.1","d":"知道电能的单位焦耳和千瓦时（度），1 kW·h = 3.6×10⁶ J；会读电能表并计算消耗的电能；知道电功 W = UIt。","mc":["会换算 kW·h 与 J","会读电能表并算出用电量","会用 W = UIt 计算电功"],"dq":{"q":"1 kW·h 等于多少焦耳？","a":"3.6×10⁶ J"}},{"id":"cnp_075","n":"电功率","g":"初3","sm":"全","ch":"九全 第十八章 电功率 18.2","d":"知道电功率表示电流做功的快慢，P = W/t = UI；知道额定电压、额定功率和实际功率；会进行简单计算。","mc":["会用 P = UI、P = W/t 计算","能区分额定功率和实际功率","会根据铭牌计算电流或电阻"],"dq":{"q":"一盏灯两端电压 220 V，通过的电流为 0.2 A，它的电功率是多少 W？（只填数值）","a":"44"}},{"id":"cnp_076","n":"跨学科实践：为家庭节约用电提建议","g":"初3","sm":"全","ch":"九全 第十八章 电功率 18.3","d":"调查家庭用电情况，运用电功和电功率知识估算用电量，从减小功率、缩短时间等方面提出节约用电的建议。","mc":["能用 W = Pt 估算家用电器用电量","能提出合理的节约用电建议"],"dq":{"q":"一台 100 W 的电视机每天待机和观看共 5 h，一个月（30 天）消耗多少 kW·h 的电能？（只填数值）","a":"15"}},{"id":"cnp_077","n":"焦耳定律","g":"初3","sm":"全","ch":"九全 第十八章 电功率 18.4","d":"通过实验了解电流的热效应，知道焦耳定律 Q = I²Rt；能用焦耳定律说明电热的利用和防止。","mc":["会用 Q = I²Rt 计算","能解释电炉丝热而导线不热等现象","能举例说明电热的利用和防止"],"dq":{"q":"电流 2 A 通过 10 Ω 的电阻，通电 60 s 产生多少 J 的热量？（只填数值）","a":"2400"}},{"id":"cnp_078","n":"安全用电","g":"初3","sm":"全","ch":"九全 第十九章 生活用电 19.1","d":"知道人体的安全电压不高于 36 V，了解触电的类型和原因，知道安全用电原则（不接触低压带电体，不靠近高压带电体）和触电急救方法。","mc":["知道安全电压","能判断安全与不安全的用电行为","知道发现触电先切断电源"],"dq":{"q":"对人体安全的电压是多少？","a":"不高于 36 V"}},{"id":"cnp_079","n":"家庭电路的基本组成","g":"初3","sm":"全","ch":"九全 第十九章 生活用电 19.2","d":"了解家庭电路的组成（进户线、电能表、总开关、保险装置、插座、灯泡、开关等），知道火线和零线、试电笔的使用、三线插头和漏电保护器的作用，知道电流过大的原因。","mc":["能说出家庭电路的组成顺序","会正确使用试电笔辨别火线零线","知道电流过大的两个原因（短路、总功率过大）"],"dq":{"q":"用试电笔辨别火线和零线时，氖管发光的是哪一根？","a":"火线"}},{"id":"cnp_080","n":"跨学科实践：为家庭电路做设计","g":"初3","sm":"全","ch":"九全 第十九章 生活用电 19.3","d":"综合家庭电路组成、安全用电和电功率知识，为房间设计电路：确定用电器连接方式、开关和插座位置，估算总功率并选择合适的导线和保险装置。","mc":["能设计各用电器并联、开关控制火线的电路","能根据总功率估算干路电流并选择器材"],"dq":{"q":"某房间同时使用 1100 W 的空调和 220 W 的电视，干路电流是多少 A？（电压 220 V，只填数值）","a":"6"}},{"id":"cnp_081","n":"磁现象 磁场","g":"初3","sm":"全","ch":"九全 第二十章 电与磁 20.1","d":"知道磁体的磁极及磁极间相互作用规律；通过实验认识磁场，知道磁感线可以形象描述磁场，磁体外部磁感线从 N 极出发回到 S 极；知道地磁场。","mc":["知道磁极间相互作用规律","知道磁感线的方向","知道地磁场的 N 极在地理南极附近"],"dq":{"q":"磁极间的相互作用规律是什么？","a":"同名磁极相互排斥，异名磁极相互吸引"}},{"id":"cnp_082","n":"电生磁","g":"初3","sm":"全","ch":"九全 第二十章 电与磁 20.2","d":"通过奥斯特实验知道电流周围存在磁场；探究并了解通电螺线管外部磁场的方向，会用安培定则判断通电螺线管的极性。","mc":["知道奥斯特实验说明电流周围有磁场","会用安培定则判断螺线管 N 极","知道螺线管外部磁场与条形磁体相似"],"dq":{"q":"首先发现电流周围存在磁场的科学家是谁？","a":"奥斯特"}},{"id":"cnp_083","n":"电磁铁 电磁继电器","g":"初3","sm":"全","ch":"九全 第二十章 电与磁 20.3","d":"知道电磁铁的磁性有无可由通断电控制，磁性强弱与电流大小和线圈匝数有关；了解电磁继电器是利用低压控制电路控制高压工作电路的开关。","mc":["能说出影响电磁铁磁性强弱的因素","知道电磁继电器的作用和原理","能举出电磁铁的应用"],"dq":{"q":"下列方法中，能增强电磁铁磁性的是哪一个？","a":"增加线圈匝数"}},{"id":"cnp_084","n":"电动机","g":"初3","sm":"全","ch":"九全 第二十章 电与磁 20.4","d":"通过实验了解通电导线在磁场中受力的作用，知道受力方向与电流方向和磁场方向有关；知道电动机的原理和能量转化，了解换向器的作用。","mc":["知道通电导线在磁场中受力及影响方向的因素","知道电动机把电能转化为机械能","知道换向器的作用"],"dq":{"q":"电动机是根据什么原理工作的？","a":"通电导线在磁场中受到力的作用"}},{"id":"cnp_085","n":"跨学科实践：制作简易直流电动机","g":"初3","sm":"全","ch":"九全 第二十章 电与磁 20.5","d":"利用磁体、漆包线、电池等制作简易直流电动机，理解线圈转动的原因，能排查不转的故障并提出改进方法。","mc":["能说出简易电动机的结构和原理","能分析线圈不转的原因并改进"],"dq":{"q":"制作简易电动机时，线圈引线一端漆皮全刮掉、另一端只刮半周，作用相当于什么？","a":"换向器"}},{"id":"cnp_086","n":"磁生电","g":"初3","sm":"全","ch":"九全 第二十章 电与磁 20.6","d":"探究并了解导体在磁场中运动时产生感应电流的条件（闭合电路的一部分导体做切割磁感线运动）；知道发电机的原理和能量转化，了解交流电。","mc":["能说出产生感应电流的条件","知道发电机把机械能转化为电能","能区分电动机和发电机的原理"],"dq":{"q":"发现电磁感应现象的科学家是谁？","a":"法拉第"}},{"id":"cnp_087","n":"电磁波的海洋","g":"初3","sm":"全","ch":"九全 第二十一章 电磁波及其应用 21.1","d":"知道电磁波的产生和传播，电磁波可以在真空中传播，速度 c = 3×10⁸ m/s；知道波长、频率和波速的关系 c = λf。","mc":["知道电磁波在真空中的传播速度","会用 c = λf 计算","知道电磁波能在真空中传播"],"dq":{"q":"电磁波在真空中的传播速度是多少？","a":"3×10⁸ m/s"}},{"id":"cnp_088","n":"广播、电视和移动通信","g":"初3","sm":"全","ch":"九全 第二十一章 电磁波及其应用 21.2","d":"了解广播、电视、移动电话利用电磁波传递信息的大致过程，知道手机既是发射台又是接收台。","mc":["知道广播、电视和手机都用电磁波传递信息","知道手机既能发射又能接收电磁波"],"dq":{"q":"手机通话时，是利用什么传递信息的？","a":"电磁波"}},{"id":"cnp_089","n":"卫星通信和光纤通信","g":"初3","sm":"全","ch":"九全 第二十一章 电磁波及其应用 21.3","d":"了解卫星通信（如北斗卫星导航系统）、光纤通信的特点；知道光纤是利用激光在光导纤维中多次反射传递信息。","mc":["知道光纤通信利用激光在光纤内反射传播","知道卫星通信和北斗系统利用电磁波"],"dq":{"q":"北斗卫星导航系统是利用什么传递信息的？","a":"电磁波"}},{"id":"cnp_090","n":"能源利用的现状和面临的挑战","g":"初3","sm":"全","ch":"九全 第二十二章 能源与可持续发展 22.1","d":"知道一次能源和二次能源、可再生能源和不可再生能源，了解化石能源的使用现状和带来的环境问题，知道能量的转化和转移具有方向性。","mc":["能区分可再生能源和不可再生能源","能举出化石能源带来的环境问题","知道能量转化具有方向性"],"dq":{"q":"下列能源中属于不可再生能源的是哪一个？","a":"石油"}},{"id":"cnp_091","n":"新能源的发展","g":"初3","sm":"全","ch":"九全 第二十二章 能源与可持续发展 22.2","d":"了解核能（裂变、聚变）、太阳能、风能等新能源，知道核电站利用核裂变、太阳内部发生核聚变，知道核能利用可能带来的问题。","mc":["知道核电站利用核裂变","知道太阳能来自太阳内部的核聚变","知道核能利用的优点和风险"],"dq":{"q":"目前核电站获得核能的途径是什么？","a":"核裂变"}},{"id":"cnp_092","n":"跨学科实践：为节约能源设计方案","g":"初3","sm":"全","ch":"九全 第二十二章 能源与可持续发展 22.3","d":"调查学校或家庭的能源使用情况，运用效率、电功率等知识估算节能效果，设计可行的节约能源方案，体会可持续发展的重要性。","mc":["能估算节能措施的节约量","能提出合理可行的节能方案"],"dq":{"q":"学校 50 盏 40 W 的日光灯，课间每天少开 2 h，每天可节约多少 kW·h 的电能？（只填数值）","a":"4"}},{"id":"cnp_h001","n":"质点和参考系","g":"高1","sm":"上","ch":"必修一 第一章 运动的描述 1.1","d":"从高中角度重新认识机械运动：理解质点是忽略物体大小和形状的理想化模型，知道能否看成质点取决于所研究的问题；理解运动的描述具有相对性，描述运动必须先选参考系。","mc":["能判断具体情境中物体能否看成质点","能说出选取不同参考系时运动描述可以不同","能选取参考系分析相对运动"],"dq":{"q":"下列各种情况中，研究对象可以看成质点的是哪一个？","a":"研究从北京开往上海的高铁全程所用的时间时的高铁"}},{"id":"cnp_h002","n":"时间、时刻和位移","g":"高1","sm":"上","ch":"必修一 第一章 运动的描述 1.2","d":"区分时刻与时间间隔；理解位移是描述位置变化的矢量，用从起点指向终点的有向线段表示，与路程不同；会在一条直线上用正负号表示位移方向，并会计算平面内的位移大小。","mc":["能区分时刻和时间间隔","能区分位移和路程并说明位移是矢量","会求直线上和平面内的位移"],"dq":{"q":"下列表示时刻的是哪一个？","a":"第 3 s 末"}},{"id":"cnp_h003","n":"平均速度和瞬时速度","g":"高1","sm":"上","ch":"必修一 第一章 运动的描述 1.3","d":"把初中的“速度”深化为矢量：平均速度等于位移与时间之比，描述一段时间内位置变化的快慢；瞬时速度描述某一时刻的运动快慢，其大小叫速率；知道用极短时间内的平均速度近似瞬时速度（极限思想）。","mc":["能区分平均速度与平均速率、瞬时速度与瞬时速率","会计算平均速度","知道用光电门等测瞬时速度的原理"],"dq":{"q":"关于平均速度，下列说法正确的是哪一个？","a":"平均速度等于位移与所用时间之比，是矢量"}},{"id":"cnp_h004","n":"加速度","g":"高1","sm":"上","ch":"必修一 第一章 运动的描述 1.4","d":"理解加速度是描述速度变化快慢的矢量，a = Δv/Δt；知道加速度方向与速度变化量方向相同，由加速度方向与速度方向的关系判断加速还是减速；会从 v-t 图像的斜率求加速度。","mc":["能说出加速度的定义式和矢量性","能用加速度与速度方向的关系判断加速、减速","会计算平均加速度及从图像求加速度"],"dq":{"q":"关于加速度，下列说法正确的是哪一个？","a":"加速度描述速度变化的快慢，是矢量"}},{"id":"cnp_h005","n":"实验：探究小车速度随时间变化的规律","g":"高1","sm":"上","ch":"必修一 第二章 匀变速直线运动的研究 2.1","d":"用打点计时器研究小车在重物牵引下的运动：会安装器材、规范操作，从纸带上取计数点，用中间时刻的瞬时速度等于平均速度求各点速度，用逐差法或 v-t 图像斜率求加速度。","mc":["知道打点计时器的工作原理和操作顺序","会由纸带用 v_t/2 = x/t 求计数点速度","会用逐差法或 v-t 图像求加速度"],"dq":{"q":"使用频率为 50 Hz 的打点计时器，纸带上每 5 个点取一个计数点（相邻计数点间有 4 个点未画出），则相邻计数点的时间间隔是多少？","a":"0.1 s"}},{"id":"cnp_h006","n":"匀变速直线运动的速度与时间的关系","g":"高1","sm":"上","ch":"必修一 第二章 匀变速直线运动的研究 2.2","d":"理解匀变速直线运动的特点是加速度不变，掌握速度公式 v = v0 + at 及其矢量性（正方向的选取），会读 v-t 图像，并能处理刹车类问题（先判断多久停下）。","mc":["能用 v = v0 + at 求速度、时间、加速度","能由 v-t 图像判断运动性质","会处理汽车刹车停下的问题"],"dq":{"q":"一辆汽车的初速度为 5 m/s，以 2 m/s² 的加速度做匀加速直线运动，6 s 末的速度是多少 m/s？（只填数值）","a":"17"}},{"id":"cnp_h007","n":"匀变速直线运动的位移与时间的关系","g":"高1","sm":"上","ch":"必修一 第二章 匀变速直线运动的研究 2.3","d":"掌握匀变速直线运动的位移公式 x = v0 t + ½at²，理解 v-t 图像与时间轴所围面积表示位移，会求某段时间内的位移（如第 n 秒内）并注意刹车问题的实际停止时间。","mc":["能用 x = v0 t + ½at² 计算位移","理解 v-t 图像面积的意义","能区分“前 n 秒内”和“第 n 秒内”"],"dq":{"q":"物体从静止开始以 2 m/s² 的加速度做匀加速直线运动，前 5 s 内的位移是多少 m？（只填数值）","a":"25"}},{"id":"cnp_h008","n":"速度与位移的关系和匀变速运动的推论","g":"高1","sm":"上","ch":"必修一 第二章 匀变速直线运动的研究 2.3","d":"掌握不含时间的关系式 v² - v0² = 2ax，以及匀变速直线运动的推论：中间时刻速度等于平均速度、位移中点速度、相邻相等时间内位移之差 Δx = aT²，能选择合适公式解题。","mc":["能用 v² - v0² = 2ax 解题","掌握中间时刻速度和 Δx = aT² 的推论","知道位移中点速度的表达式"],"dq":{"q":"飞机从静止开始在跑道上以 3 m/s² 的加速度做匀加速直线运动，起飞速度为 60 m/s，跑道至少多长？（单位 m，只填数值）","a":"600"}},{"id":"cnp_h009","n":"自由落体运动","g":"高1","sm":"上","ch":"必修一 第二章 匀变速直线运动的研究 2.4","d":"认识自由落体运动：只在重力作用下由静止开始下落，加速度为重力加速度 g，是初速度为零的匀加速直线运动；会用匀变速公式求下落时间、速度、高度，并知道亚里士多德与伽利略的认识差异。","mc":["能说出自由落体运动的条件和特点","会用 h = ½gt²、v = gt 计算","会处理“最后 1 s”“间隔相等的水滴”等问题"],"dq":{"q":"一物体从 20 m 高处由静止自由下落，不计空气阻力，g 取 10 m/s²，落地需要多少 s？（只填数值）","a":"2"}},{"id":"cnp_h010","n":"重力","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.1","d":"从高中角度认识重力：重力是由于地球的吸引而使物体受到的力，G = mg，方向竖直向下；g 随纬度和高度略有变化；重心是重力的等效作用点，其位置与质量分布和形状有关，不一定在物体上。","mc":["能说出重力的方向和大小 G = mg","理解重心的含义及位置特点","知道质量不变、重力随地点改变"],"dq":{"q":"关于重力的方向，下列说法正确的是哪一个？","a":"竖直向下"}},{"id":"cnp_h011","n":"弹力与胡克定律","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.1","d":"理解弹力是发生弹性形变的物体对与它接触的物体的作用力；会判断压力、支持力、拉力的方向；掌握胡克定律 F = kx（x 为形变量，k 为劲度系数），注意单位换算和弹性限度。","mc":["能判断弹力的产生条件和方向","能用胡克定律 F = kx 计算","理解劲度系数 k 与形变量 x 的含义"],"dq":{"q":"某轻弹簧的劲度系数 k = 200 N/m，在弹性限度内被拉长了 5 cm，弹簧弹力是多少 N？（只填数值）","a":"10"}},{"id":"cnp_h012","n":"实验：探究弹簧弹力与形变量的关系","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.1","d":"探究弹簧弹力与形变量的关系：用悬挂钩码的方法，测量不同拉力下弹簧的长度，作 F-x（或 F-l）图像，由斜率得到劲度系数，由图线与坐标轴的交点理解原长，注意弹性限度和读数时钩码静止。","mc":["知道实验原理、器材和操作要点","会作 F-x 图像并由斜率求 k","能分析图线弯曲、截距的含义"],"dq":{"q":"关于“探究弹簧弹力与形变量的关系”的实验操作，下列说法正确的是哪一个？","a":"待钩码静止后再读出弹簧的长度"}},{"id":"cnp_h013","n":"静摩擦力","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.2","d":"认识静摩擦力：相互接触且挤压、接触面粗糙、有相对运动趋势时产生；方向与相对运动趋势方向相反（可以与运动方向相同）；大小由平衡条件或牛顿运动定律确定，有最大值，与压力无必然关系。","mc":["能判断静摩擦力的有无和方向","知道静摩擦力随外力变化且有最大值","会用平衡条件求静摩擦力大小"],"dq":{"q":"质量为 20 kg 的木箱放在水平地面上，木箱与地面间的动摩擦因数为 0.4（最大静摩擦力近似等于滑动摩擦力），g 取 10 m/s²。用 50 N 的水平力推木箱没有推动，木箱受到的摩擦力大小是多少？","a":"50 N"}},{"id":"cnp_h014","n":"滑动摩擦力","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.2","d":"掌握滑动摩擦力 f = μN：N 为接触面间的正压力，μ 为动摩擦因数，与接触面积、速度大小无关；方向与相对运动方向相反（可以与物体运动方向相同）；求 N 时要通过受力分析。","mc":["会用 f = μN 计算滑动摩擦力","知道滑动摩擦力与接触面积、速度无关","能判断滑动摩擦力的方向"],"dq":{"q":"质量为 5 kg 的木箱在水平地面上滑动，木箱与地面间的动摩擦因数为 0.2，g 取 10 m/s²，木箱受到的滑动摩擦力是多少 N？（只填数值）","a":"10"}},{"id":"cnp_h015","n":"牛顿第三定律","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.3","d":"理解牛顿第三定律：两个物体之间的作用力和反作用力总是大小相等、方向相反、作用在同一条直线上，分别作用在两个物体上，同时产生、同时消失、性质相同；能区分相互作用力与平衡力。","mc":["能说出牛顿第三定律的内容","能区分作用力与反作用力和平衡力","能用第三定律分析实际问题"],"dq":{"q":"马拉着车加速前进时，马对车的拉力 F1 与车对马的拉力 F2 的关系是哪一个？","a":"大小相等、方向相反"}},{"id":"cnp_h016","n":"力的合成","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.4","d":"理解合力与分力的等效替代关系，知道力是矢量，求合力遵循平行四边形定则；会求两个力互成任意角时的合力，知道两个力的合力范围 |F1 - F2| ≤ F ≤ F1 + F2，会判断三个力合力的最小值。","mc":["会用平行四边形定则求合力","能确定两个力、三个力的合力范围","理解矢量和标量的区别"],"dq":{"q":"两个互相垂直的力，大小分别为 3 N 和 4 N，它们的合力大小是多少 N？（只填数值）","a":"5"}},{"id":"cnp_h017","n":"实验：探究两个互成角度的力的合成规律","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.4","d":"探究两个互成角度的力的合成规律：用两个弹簧测力计和一个弹簧测力计分别把橡皮条拉到同一位置，记录结点位置和力的大小、方向，按同一标度作力的图示，比较平行四边形的对角线与单个力，体会等效替代，并分析误差。","mc":["理解等效替代法及结点位置相同的原因","知道操作要点和减小误差的方法","能区分理论合力与实验合力并分析误差"],"dq":{"q":"该实验中，两次都要把橡皮条的结点拉到同一位置 O，这是为了什么？","a":"使两次力的作用效果相同，体现等效替代"}},{"id":"cnp_h018","n":"力的分解","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.4","d":"理解力的分解是力的合成的逆运算，同样遵循平行四边形定则；掌握按力的实际作用效果分解、正交分解的方法；能求重力沿斜面和垂直斜面的分力，以及已知条件下的分力最小值。","mc":["能按实际效果或正交分解法分解力","会求斜面上重力的两个分力","会分析分力的最小值问题"],"dq":{"q":"与水平方向成 37° 斜向上的 100 N 拉力，其水平分力的大小是多少 N？（cos37° = 0.8，只填数值）","a":"80"}},{"id":"cnp_h019","n":"共点力的平衡","g":"高1","sm":"上","ch":"必修一 第三章 相互作用——力 3.5","d":"理解共点力平衡的条件是合力为零，物体处于静止或匀速直线运动状态；会用合成法、正交分解法分析斜面、悬挂等平衡问题，能分析力缓慢变化的动态平衡。","mc":["能判断物体是否处于平衡状态","会列平衡方程求未知力","能分析简单的动态平衡问题"],"dq":{"q":"下列物体中，处于平衡状态的是哪一个？","a":"沿斜面匀速下滑的木块"}},{"id":"cnp_h020","n":"牛顿第一定律","g":"高1","sm":"上","ch":"必修一 第四章 运动和力的关系 4.1","d":"理解牛顿第一定律：一切物体总保持匀速直线运动状态或静止状态，除非作用在它上面的力迫使它改变这种状态。了解伽利略理想斜面实验的推理过程，认识力是改变物体运动状态的原因而不是维持运动的原因。","mc":["能陈述牛顿第一定律并说明力与运动的关系","能复述伽利略理想斜面实验的结论","知道牛顿第一定律是科学推理的结果，不能直接用实验验证"],"dq":{"q":"一个物体不受任何外力作用时，它将处于什么状态？","a":"保持静止或匀速直线运动状态"}},{"id":"cnp_h021","n":"惯性与质量","g":"高1","sm":"上","ch":"必修一 第四章 运动和力的关系 4.1","d":"知道惯性是物体保持原来匀速直线运动状态或静止状态的性质，一切物体都有惯性；质量是惯性大小的唯一量度，与速度、受力和所处位置无关。能用惯性解释生活中的现象。","mc":["知道惯性大小只由质量决定","能用惯性解释刹车、起动等现象","不把惯性当作一种力"],"dq":{"q":"物体惯性的大小由下列哪个因素决定？","a":"物体的质量"}},{"id":"cnp_h022","n":"实验：探究加速度与力、质量的关系","g":"高1","sm":"上","ch":"必修一 第四章 运动和力的关系 4.2","d":"用控制变量法，以小车、槽码和打点计时器探究加速度与合力、质量的关系：平衡摩擦力，槽码质量远小于小车质量，用纸带求加速度，作 a-F 和 a-1/m 图像得出结论。","mc":["知道平衡摩擦力的方法与槽码质量远小于小车质量的条件","会用逐差法由纸带求加速度","会由 a-F、a-1/m 图线分析误差与结论"],"dq":{"q":"探究加速度与质量的关系时，改变小车质量，应保持哪个量不变？","a":"细线对小车的拉力（小车所受合力）"}},{"id":"cnp_h023","n":"牛顿第二定律","g":"高1","sm":"上","ch":"必修一 第四章 运动和力的关系 4.3","d":"理解牛顿第二定律：物体加速度的大小跟所受合力成正比，跟质量成反比，方向与合力方向相同，F合 = ma。注意矢量性（a 与 F合 同向）、瞬时性（a 与 F合 同时产生、变化、消失）和同体性（F、m、a 对应同一物体）。","mc":["能说明 F合 = ma 的矢量性、瞬时性、同体性","会求物体所受合力并计算加速度","能分析弹簧、细线突变时的瞬时加速度"],"dq":{"q":"关于牛顿第二定律，下列说法正确的是哪一个？","a":"物体加速度的方向总与它所受合外力的方向相同"}},{"id":"cnp_h024","n":"力学单位制","g":"高1","sm":"上","ch":"必修一 第四章 运动和力的关系 4.4","d":"知道国际单位制中力学的三个基本量（长度、质量、时间）及其基本单位米、千克、秒，知道导出单位由物理公式推出，例如 1 N = 1 kg·m/s²。能用单位制检验公式并做单位换算。","mc":["能区分基本单位和导出单位","会用 1 N = 1 kg·m/s² 做单位换算","能用单位检查公式是否合理"],"dq":{"q":"下列单位中，属于国际单位制中力学基本单位的是哪一个？","a":"千克"}},{"id":"cnp_h025","n":"牛顿运动定律的应用","g":"高1","sm":"上","ch":"必修一 第四章 运动和力的关系 4.5","d":"用牛顿第二定律与运动学公式解决两类问题：已知受力求运动，已知运动求受力。关键是受力分析、选取坐标、求合力，用加速度联系力和运动，斜面和摩擦问题要分解重力。","mc":["能由受力求加速度再求运动量","能由运动求加速度再求某个力","会分析斜面上的受力并求加速度"],"dq":{"q":"质量为 1000 kg 的汽车以 20 m/s 的速度行驶，刹车后做匀减速直线运动，经 5 s 停下。汽车受到的阻力大小是多少 N？（只填数值）","a":"4000"}},{"id":"cnp_h026","n":"连接体问题与整体法、隔离法","g":"高1","sm":"上","ch":"必修一 第四章 运动和力的关系 4.5","d":"分析几个物体连在一起运动的问题：加速度相同时，用整体法求加速度，再用隔离法求物体间的相互作用力；注意绳上张力、叠放物体间摩擦力的求法，以及不发生相对滑动的临界条件。","mc":["会用整体法求系统加速度","会用隔离法求内力（绳的拉力、接触面作用力）","能由最大静摩擦力求叠放物体不相对滑动的临界条件"],"dq":{"q":"质量 m₁ = 3 kg 和 m₂ = 2 kg 的两个物体用轻绳相连，放在光滑水平面上，用水平拉力 F = 20 N 拉 m₂，使 m₁、m₂ 一起运动。它们的加速度大小是多少 m/s²？（只填数值）","a":"4"}},{"id":"cnp_h027","n":"超重和失重","g":"高1","sm":"上","ch":"必修一 第四章 运动和力的关系 4.6","d":"理解超重和失重：物体对支持物的压力（或对悬挂物的拉力）大于重力为超重，小于重力为失重，等于零为完全失重。判断依据是加速度方向：向上超重，向下失重，a = g 向下时完全失重，此时重力并未改变。","mc":["能由加速度方向判断超重与失重","会算超重或失重时的视重","知道完全失重时重力依然存在"],"dq":{"q":"物体处于超重状态时，下列说法正确的是哪一个？","a":"物体对支持物的压力大于物体所受的重力"}},{"id":"cnp_h028","n":"曲线运动","g":"高2","sm":"上","ch":"必修二 第五章 抛体运动 5.1","d":"知道曲线运动中质点在某点的速度方向沿轨迹的切线方向，曲线运动一定是变速运动；掌握物体做曲线运动的条件是合力方向与速度方向不在同一直线上，合力总指向轨迹凹侧。","mc":["知道曲线运动速度方向沿切线","会判断物体做曲线运动的条件","会由轨迹弯曲方向判断合力方向"],"dq":{"q":"做曲线运动的质点，在某一位置的速度方向是怎样的？","a":"沿轨迹在该点的切线方向"}},{"id":"cnp_h029","n":"运动的合成与分解","g":"高2","sm":"上","ch":"必修二 第五章 抛体运动 5.2","d":"理解合运动与分运动：分运动具有独立性和等时性，位移、速度、加速度的合成遵循平行四边形定则。会用合成与分解分析小船渡河等问题，判断合运动的轨迹是直线还是曲线。","mc":["知道合运动与分运动的等时性和独立性","会用平行四边形定则求合速度和合位移","会分析小船渡河的最短时间和最短位移"],"dq":{"q":"关于合运动与分运动，下列说法正确的是哪一个？","a":"合运动与分运动经历的时间相等"}},{"id":"cnp_h030","n":"实验：探究平抛运动的特点","g":"高2","sm":"上","ch":"必修二 第五章 抛体运动 5.3","d":"通过实验探究平抛运动：用小锤击打金属片使两球同时下落，说明竖直分运动是自由落体；用斜槽、坐标纸描点画出轨迹，会通过轨迹或频闪照片求初速度，知道斜槽末端要水平、小球要从同一位置释放。","mc":["知道平抛实验装置的调节要求","知道两球同时落地说明了什么","会由轨迹上的点求平抛初速度"],"dq":{"q":"做“探究平抛运动的特点”实验时，要求斜槽末端切线水平，目的是什么？","a":"保证小球离开斜槽时的速度沿水平方向"}},{"id":"cnp_h031","n":"平抛运动的规律","g":"高2","sm":"上","ch":"必修二 第五章 抛体运动 5.4","d":"掌握平抛运动的规律：水平方向做匀速直线运动 x = v₀t，竖直方向做自由落体运动 y = gt²/2；落地时间只由下落高度决定，速度和位移都用分解与合成求解，斜面上的平抛要利用位移与水平方向夹角。","mc":["会求平抛运动的时间、射程和落地速度","会用 vy/vx 和 y/x 表示速度、位移的方向","会处理落在斜面上的平抛问题"],"dq":{"q":"不计空气阻力，平抛运动在空中运动的时间决定于","a":"下落的高度"}},{"id":"cnp_h032","n":"斜抛运动","g":"高2","sm":"上","ch":"必修二 第五章 抛体运动 5.4","d":"把斜抛运动分解为水平方向的匀速直线运动（vx = v₀cosθ）和竖直方向的匀变速运动（vy = v₀sinθ − gt）。最高点速度水平但不为零，能求射高、射程和飞行时间，知道互余抛射角射程相同。","mc":["会把初速度分解为水平和竖直分量","能求斜抛运动的上升时间、射高和射程","知道最高点速度不为零，加速度仍为 g"],"dq":{"q":"不计空气阻力，斜上抛运动的物体到达最高点时，下列说法正确的是（初速度 v₀，抛射角 θ）","a":"速度沿水平方向，大小为 v₀cosθ，加速度仍为 g"}},{"id":"cnp_h033","n":"圆周运动的描述","g":"高2","sm":"上","ch":"必修二 第六章 圆周运动 6.1","d":"用线速度、角速度和周期描述匀速圆周运动：v = Δs/Δt，ω = Δθ/Δt（θ 用弧度，单位 rad/s），T = 2π/ω，v = ωr，ω = 2πn。知道匀速圆周运动的线速度方向时刻改变，是变速运动，会分析皮带传动和同轴转动。","mc":["会用 v、ω、T、n 的关系式做计算，转速单位要换算","知道匀速圆周运动速度大小不变而方向改变","会比较皮带传动与同轴转动中的 v 和 ω"],"dq":{"q":"关于匀速圆周运动，下列说法正确的是哪一个？","a":"线速度大小不变、方向时刻改变，是变速运动"}},{"id":"cnp_h034","n":"向心力","g":"高2","sm":"上","ch":"必修二 第六章 圆周运动 6.2","d":"知道做匀速圆周运动的物体需要一个始终指向圆心的合力提供向心力，大小 F = mv²/r = mω²r。向心力是按作用效果命名的力，由某个力或几个力的合力提供，不是另外的性质力，受力分析时不能多画。","mc":["知道向心力是效果力，不是新的性质力","会用 F = mv²/r、F = mω²r 计算","能判断具体情境中向心力的来源"],"dq":{"q":"关于向心力，下列说法正确的是哪一个？","a":"向心力是按作用效果命名的力，由物体所受的某个力或几个力的合力提供"}},{"id":"cnp_h035","n":"实验：探究向心力大小与半径、角速度、质量的关系","g":"高2","sm":"上","ch":"必修二 第六章 圆周运动 6.2","d":"用向心力演示器（变速塔轮、标尺和测力套筒）探究向心力与质量、角速度、半径的关系：用控制变量法，由左右标尺露出的格数之比得到向心力之比，由塔轮半径比得到角速度比。","mc":["能说明控制变量的做法","会由塔轮半径之比求角速度比和向心力之比","会用 F = mω²r 处理实验数据"],"dq":{"q":"探究向心力与角速度的关系时，应保持不变的量是","a":"小球的质量和转动半径"}},{"id":"cnp_h036","n":"向心加速度","g":"高2","sm":"上","ch":"必修二 第六章 圆周运动 6.3","d":"知道匀速圆周运动的加速度方向始终指向圆心，叫向心加速度，大小 aₙ = v²/r = ω²r = 4π²r/T²。方向时刻改变，是变加速运动。会由牛顿第二定律联系向心力与向心加速度。","mc":["知道向心加速度的方向和意义","会用 aₙ = v²/r = ω²r 计算","会比较传动装置中各点的向心加速度"],"dq":{"q":"做匀速圆周运动的物体，其向心加速度的方向是","a":"总是指向圆心，方向时刻改变"}},{"id":"cnp_h037","n":"生活中的圆周运动","g":"高2","sm":"上","ch":"必修二 第六章 圆周运动 6.4","d":"用牛顿第二定律分析生活中的圆周运动：汽车过拱桥和凹桥、水平路面转弯、火车转弯、竖直平面内的绳球模型等。关键是确定圆心位置，沿半径方向列式 F合 = mv²/r。","mc":["会分析汽车过凸桥、凹桥的受力并比较压力与重力","会求水平转弯的最大速率","会处理绳球模型最高点的受力"],"dq":{"q":"汽车以速度 v 通过半径为 r 的凸形拱桥顶部，且 v < √(gr)，此时汽车对桥面的压力","a":"小于车重，车处于失重状态"}},{"id":"cnp_h038","n":"离心现象","g":"高2","sm":"上","ch":"必修二 第六章 圆周运动 6.4","d":"知道离心运动是物体所受合力不足以提供所需向心力（或合力消失）时，逐渐远离圆心的运动。不存在“离心力”。能分析脱水、转弯侧滑等例子，并区分离心现象的应用与防止。","mc":["能说明离心现象的产生条件，知道没有离心力","能判断绳断、转盘滑动后物体的运动","能区分离心现象的应用与防止"],"dq":{"q":"物体做离心运动的原因是什么？","a":"物体所受合力不足以提供所需的向心力"}},{"id":"cnp_h039","n":"行星的运动","g":"高2","sm":"上","ch":"必修二 第七章 万有引力与宇宙航行 7.1","d":"学习开普勒三大定律：行星沿椭圆轨道运动，太阳在椭圆的一个焦点上；行星与太阳连线在相等时间内扫过相等的面积；轨道半长轴的三次方与公转周期的二次方之比为定值。","mc":["能说出开普勒三大定律的内容","知道近日点速率大、远日点速率小","会用 a³/T² = k 比较或计算不同行星的轨道和周期"],"dq":{"q":"关于开普勒第一定律，下列说法正确的是哪一个？","a":"所有行星绕太阳运动的轨道都是椭圆，太阳处在椭圆的一个焦点上"}},{"id":"cnp_h040","n":"万有引力定律","g":"高2","sm":"上","ch":"必修二 第七章 万有引力与宇宙航行 7.2","d":"万有引力定律指出，任何两个物体间都存在相互吸引的力，大小与两物体质量的乘积成正比，与它们距离的二次方成反比，F = Gm₁m₂/r²；引力常量 G 由卡文迪什用扭秤实验测出。","mc":["能写出万有引力定律的表达式并说明各量含义","会用平方反比关系比较不同距离处的引力","知道万有引力是一对作用力与反作用力"],"dq":{"q":"两个质点间的距离变为原来的 2 倍，其余条件不变，它们间的万有引力变为原来的多少？","a":"原来的 1/4"}},{"id":"cnp_h041","n":"万有引力理论的成就","g":"高2","sm":"上","ch":"必修二 第七章 万有引力与宇宙航行 7.3","d":"把天体的圆周运动看作万有引力提供向心力，可由环绕天体的轨道半径和周期算出中心天体的质量，再结合中心天体的半径求出密度；也可由表面重力加速度 g = GM/R² 求天体质量。","mc":["会由 GMm/r² = m·4π²r/T² 求中心天体质量","会用 g = GM/R² 比较和计算天体表面的重力加速度","能求近地环绕时中心天体的密度"],"dq":{"q":"卫星绕地球做匀速圆周运动，已知它的轨道半径 r 和周期 T，仅凭这两个量和引力常量 G，能求出下列哪个量？","a":"地球的质量"}},{"id":"cnp_h042","n":"宇宙速度","g":"高2","sm":"上","ch":"必修二 第七章 万有引力与宇宙航行 7.4","d":"第一宇宙速度 7.9 km/s 是卫星贴近地面做圆周运动的速度，既是最大环绕速度，也是最小发射速度；第二宇宙速度 11.2 km/s 使物体脱离地球，第三宇宙速度 16.7 km/s 使物体飞出太阳系。","mc":["能说出三个宇宙速度的数值与物理意义","会用 mg = mv²/R 或 GMm/R² = mv²/R 推导第一宇宙速度","能比较不同天体的第一宇宙速度"],"dq":{"q":"第一宇宙速度（环绕速度）的大小约为多少？","a":"7.9 km/s"}},{"id":"cnp_h043","n":"人造卫星的运行规律","g":"高2","sm":"上","ch":"必修二 第七章 万有引力与宇宙航行 7.4","d":"卫星绕地球做匀速圆周运动时万有引力提供向心力，线速度、角速度、周期、向心加速度都由轨道半径决定：轨道越高，v、ω、a 越小，T 越大；同步卫星的轨道和周期固定。","mc":["会由 GMm/r² = mv²/r = mω²r = m4π²r/T² = ma 推出各量与 r 的关系","能比较不同轨道卫星的 v、ω、T、a","知道地球同步卫星的特点"],"dq":{"q":"地球卫星绕地球做匀速圆周运动，当轨道半径增大时，下列各量的变化正确的是哪一个？","a":"线速度、角速度、向心加速度都减小，周期增大"}},{"id":"cnp_h044","n":"相对论时空观与牛顿力学的局限性","g":"高2","sm":"上","ch":"必修二 第七章 万有引力与宇宙航行 7.5","d":"狭义相对论的两个基本假设是相对性原理与光速不变原理，由此得到时间延缓和长度收缩效应；牛顿力学只适用于宏观物体的低速运动，不能用于微观高速的情形。","mc":["能说出光速不变原理和牛顿力学的适用范围","能定性说明时间延缓、长度收缩","会用 l = l₀√(1 − v²/c²) 做简单计算"],"dq":{"q":"狭义相对论的光速不变原理指的是什么？","a":"真空中的光速在不同的惯性参考系中大小都相同"}},{"id":"cnp_h045","n":"功","g":"高2","sm":"上","ch":"必修二 第八章 机械能守恒定律 8.1","d":"力对物体做功要看力和物体在力的方向上的位移，W = Fl cosα（α 为力与位移的夹角）；功是标量，0° ≤ α < 90° 做正功，α = 90° 不做功，90° < α ≤ 180° 做负功（克服该力做功）；总功等于各力做功的代数和。","mc":["会用 W = Fl cosα 计算恒力的功","理解功是标量，会判断正功、负功和不做功","会求合力的功或各力做功的代数和"],"dq":{"q":"用 10 N 的力沿与水平方向成 60° 角斜向上拉一个木箱，使木箱沿水平地面前进 4 m，这个拉力做的功是多少 J？（cos60° = 0.5，只填数值）","a":"20"}},{"id":"cnp_h046","n":"功率","g":"高2","sm":"上","ch":"必修二 第八章 机械能守恒定律 8.1","d":"功率表示做功的快慢。P = W/t 求的是时间 t 内的平均功率；P = Fv cosα 中若 v 是瞬时速度则求瞬时功率，若 v 是平均速度则求平均功率。汽车以额定功率行驶时 F = P/v。","mc":["能区分平均功率与瞬时功率","会用 P = W/t 和 P = Fv 进行计算","会分析机车以额定功率运动的最大速度"],"dq":{"q":"用 P = W/t 计算出来的功率是哪一个功率？（t 为做功用的时间）","a":"这段时间内的平均功率"}},{"id":"cnp_h047","n":"重力势能","g":"高2","sm":"上","ch":"必修二 第八章 机械能守恒定律 8.2","d":"物体由于被举高而具有的能量叫重力势能，Ep = mgh，h 是相对参考平面的高度，Ep 的大小与参考平面的选取有关；重力做功与路径无关，WG = Ep1 − Ep2，重力做正功势能减少。","mc":["会用 Ep = mgh 计算重力势能并说明参考平面的作用","知道重力做功与路径无关","能由重力做功判断重力势能的变化"],"dq":{"q":"质量为 2 kg 的物体位于地面上方 5 m 高处，以地面为参考平面，它的重力势能是多少 J？（g 取 10 m/s²，只填数值）","a":"100"}},{"id":"cnp_h048","n":"弹性势能","g":"高2","sm":"上","ch":"必修二 第八章 机械能守恒定律 8.2","d":"发生弹性形变的物体各部分之间由于有弹力相互作用而具有的能量叫弹性势能。弹簧的弹性势能与形变量和劲度系数有关，形变量越大势能越大；弹力做正功弹性势能减少，克服弹力做功弹性势能增加。","mc":["知道弹性势能的大小与形变量有关","能由弹力做功判断弹性势能的变化","会用 F-x 图像面积求克服弹力做的功"],"dq":{"q":"一根轻弹簧的原长为 10 cm，分别被拉长到 12 cm 和被压缩到 8 cm（都在弹性限度内），这两种状态下弹簧的弹性势能的关系是什么？","a":"相等"}},{"id":"cnp_h049","n":"动能","g":"高2","sm":"上","ch":"必修二 第八章 机械能守恒定律 8.3","d":"物体由于运动而具有的能量叫动能，Ek = ½mv²。动能是标量，只有大小，不会为负，与速度方向无关；速度变化时动能不一定变化（如匀速圆周运动），动能与速度的二次方成正比。","mc":["会用 Ek = ½mv² 计算动能并比较动能大小","知道动能是标量且与速度方向无关","能处理速度单位换算与动能变化量的计算"],"dq":{"q":"质量为 2 kg 的物体以 3 m/s 的速度运动，它的动能是多少 J？（只填数值）","a":"9"}},{"id":"cnp_h050","n":"动能定理","g":"高2","sm":"上","ch":"必修二 第八章 机械能守恒定律 8.3","d":"动能定理：合力对物体做的总功等于物体动能的变化量，W合 = Ek2 − Ek1。它适用于恒力、变力、直线、曲线运动，只需关注初末状态和过程中各力的功，不必分析中间细节。","mc":["能写出动能定理并说明总功的含义","会用动能定理求速度、位移或某个力","能处理含变力做功的单过程问题"],"dq":{"q":"质量为 2 kg 的物体在合力作用下，速度由 2 m/s 增大到 6 m/s，合力对物体做的功是多少 J？（只填数值）","a":"32"}},{"id":"cnp_h051","n":"机械能守恒定律","g":"高2","sm":"上","ch":"必修二 第八章 机械能守恒定律 8.4","d":"在只有重力或弹力做功的物体系统内，动能与势能可以相互转化，而机械能的总量保持不变。判断机械能是否守恒要看是否只有重力或系统内弹力做功，再用 Ek1 + Ep1 = Ek2 + Ep2 列式。","mc":["能判断一个过程机械能是否守恒","会用机械能守恒定律求速度或高度","能结合圆周运动求某点的受力"],"dq":{"q":"机械能守恒的条件是什么？","a":"只有重力或系统内的弹力做功"}},{"id":"cnp_h052","n":"实验：验证机械能守恒定律","g":"高2","sm":"上","ch":"必修二 第八章 机械能守恒定律 8.5","d":"利用重物自由下落，由纸带上的点测出下落高度 h 和对应瞬时速度 v，比较 mgh 与 ½mv²（或 gh 与 v²/2）是否相等来验证机械能守恒；瞬时速度用中间时刻的平均速度求出，不能用 v = gt 或 v = √(2gh)。","mc":["能说出实验器材、操作顺序与注意事项","会由纸带用平均速度法求某点的瞬时速度","会计算重力势能减少量与动能增加量并分析误差"],"dq":{"q":"在「验证机械能守恒定律」的实验中，下列说法正确的是哪一个？","a":"只需验证 gh 与 v²/2 是否相等，不需要测量重物的质量"}},{"id":"cnp_h053","n":"电荷","g":"高3","sm":"上","ch":"必修三 第九章 静电场及其应用 9.1","d":"自然界只有正、负两种电荷，同种相斥、异种相吸；摩擦起电、接触起电和感应起电的实质都是电子的转移，电荷既不会创生也不会消失，总量不变（电荷守恒定律）；最小的电荷量是元电荷 e = 1.6×10⁻¹⁹ C。","mc":["能说明三种起电方式的实质是电子转移","会用电荷守恒定律和平分规律求接触后的带电量","知道元电荷并会算物体得失电子数"],"dq":{"q":"摩擦起电的实质是什么？","a":"电子从一个物体转移到另一个物体"}},{"id":"cnp_h054","n":"库仑定律","g":"高3","sm":"上","ch":"必修三 第九章 静电场及其应用 9.2","d":"库仑定律：真空中两个静止点电荷之间的相互作用力与电荷量乘积成正比，与距离的二次方成反比，作用力沿它们的连线，F = kq₁q₂/r²，k = 9.0×10⁹ N·m²/C²；同种电荷相斥，异种电荷相吸。","mc":["会用 F = kq₁q₂/r² 计算库仑力的大小","能判断库仑力的方向并比较变化倍数","会分析点电荷的平衡问题"],"dq":{"q":"真空中有两个静止的点电荷，电荷量都是 2×10⁻⁶ C，相距 0.2 m，它们间库仑力的大小是多少 N？（k = 9×10⁹ N·m²/C²，只填数值）","a":"0.9"}},{"id":"cnp_h055","n":"电场强度","g":"高3","sm":"上","ch":"必修三 第九章 静电场及其应用 9.3","d":"电场是电荷周围存在的特殊物质。电场强度 E = F/q 是比值定义，描述电场的强弱，由电场本身决定，与试探电荷无关；方向规定为正电荷在该点所受电场力的方向。真空中点电荷的场强 E = kQ/r²。","mc":["理解 E = F/q 是比值定义，与 F、q 无关","会判断场强方向（正电荷受力方向）","会用 E = kQ/r² 计算点电荷的场强"],"dq":{"q":"在电场中某点放入电荷量为 2×10⁻⁹ C 的试探电荷，它受到的电场力为 6×10⁻⁶ N，该点的电场强度是多少 N/C？（只填数值）","a":"3000"}},{"id":"cnp_h056","n":"电场线与电场的叠加","g":"高3","sm":"上","ch":"必修三 第九章 静电场及其应用 9.3","d":"电场线是描述电场的假想曲线：切线方向表示场强方向，疏密表示场强大小，从正电荷（或无穷远）出发到负电荷（或无穷远）止，不相交。多个电荷的场强遵循矢量叠加（平行四边形定则）。","mc":["能说出电场线的性质，会判断场强的大小与方向","会用平行四边形定则叠加场强","能判断电荷在电场中受力和运动方向"],"dq":{"q":"关于电场线，下列说法正确的是哪一个？","a":"电场线的疏密表示场强的强弱，任意两条电场线不会相交"}},{"id":"cnp_h057","n":"静电的防止与利用","g":"高3","sm":"上","ch":"必修三 第九章 静电场及其应用 9.4","d":"导体处于静电平衡时，内部场强处处为零，净电荷只分布在外表面，由此有静电屏蔽；尖端附近电场很强，会发生尖端放电。避雷针、静电除尘、静电喷涂是静电的利用，油罐车拖地铁链等是防止静电危害。","mc":["能说出静电平衡导体的特点","能解释静电屏蔽和尖端放电","能区分静电的利用与防止"],"dq":{"q":"高压带电作业的工人穿着用金属丝编织的均压服，主要利用了什么原理？","a":"静电屏蔽"}},{"id":"cnp_h058","n":"电势能","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.1","d":"静电力做功只与电荷的初末位置有关，与路径无关，所以可以引入电势能。静电力做的功等于电势能的减少量，W_AB = E_pA − E_pB；电势能的数值与零势能点的选取有关，变化量与之无关。","mc":["能判断静电力做功的正负，并据此判断电势能的增减","会用 W_AB = E_pA − E_pB 和 W = qEd 计算","知道电势能是电荷与电场共有的、具有相对性的量"],"dq":{"q":"在孤立正点电荷 Q 形成的电场中，把一个正试探电荷从离 Q 较近的 A 点移到离 Q 较远的 B 点。静电力做功和电势能的变化是哪一个？","a":"静电力做正功，电势能减少"}},{"id":"cnp_h059","n":"电势","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.1","d":"电荷在电场中某点的电势能与它的电荷量之比叫做这点的电势，φ = E_p/q。电势是标量，只有大小（可正可负），沿电场线方向电势逐渐降低，其数值与零电势点的选取有关。","mc":["理解电势的定义式 φ = E_p/q，知道它由电场本身决定，与试探电荷无关","能判断沿电场线方向电势的变化和点电荷电场中电势的高低","知道电势的相对性，会换算改变零电势点后的电势"],"dq":{"q":"关于电场中某点的电势，下列说法正确的是哪一个？","a":"电势是标量，其数值与零电势点的选取有关"}},{"id":"cnp_h060","n":"电势差","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.2","d":"电场中两点电势之差叫电势差，U_AB = φ_A − φ_B，且 U_AB = −U_BA。静电力做功与电势差的关系为 W_AB = qU_AB。电势差与零电势点的选取无关，是标量，有正负。","mc":["会用 U_AB = φ_A − φ_B 和 W_AB = qU_AB 计算（代入 q 与 W 的正负号）","知道电势差与零电势点的选取无关，U_AB = −U_BA","能根据电势差的正负判断两点电势的高低"],"dq":{"q":"把电荷量 q = 2×10⁻⁶ C 的正电荷从电场中的 A 点移到 B 点，静电力做功 6×10⁻⁴ J。A、B 两点的电势差 U_AB 是多少 V？（只填数值）","a":"300"}},{"id":"cnp_h061","n":"等势面","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.2","d":"电场中电势相同的点构成的面叫等势面。在同一等势面上移动电荷，静电力不做功；电场线与等势面处处垂直，并且由电势高的等势面指向电势低的等势面。相邻等势面电势差相等时，等势面越密的地方电场越强。","mc":["知道电场线与等势面垂直，沿等势面移动电荷静电力不做功","能由等势面的疏密比较场强大小，由电场线方向判断电势高低","会用 W = qU 计算电荷在不同等势面之间移动时静电力做的功"],"dq":{"q":"关于等势面，下列说法正确的是哪一个？","a":"电场线与等势面处处垂直，沿等势面移动电荷静电力不做功"}},{"id":"cnp_h062","n":"电势差与电场强度的关系","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.3","d":"匀强电场中，沿电场方向两点间的电势差等于电场强度与这两点沿电场方向距离的乘积，U = Ed，即 E = U/d。公式只适用于匀强电场，d 是沿电场方向的距离；非匀强电场中可用它定性比较电势差。","mc":["会用 U = Ed 计算匀强电场中两点间的电势差或场强","明确 d 是沿电场方向的距离，能处理两点连线与电场线成夹角的情形","能在非匀强电场中用 E 的大小定性比较相等间距两点的电势差"],"dq":{"q":"在匀强电场中，沿电场方向相距 4 cm 的两点之间的电势差是多少 V？已知电场强度 E = 500 V/m。（只填数值）","a":"20"}},{"id":"cnp_h063","n":"电容器的电容","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.4","d":"电容器由两个彼此绝缘的导体组成，电容 C = Q/U 描述容纳电荷的本领，由电容器本身结构决定。平行板电容器的电容与正对面积、相对介电常数 ε_r 成正比，与板间距离成反比，C = ε_rS/(4πkd)。","mc":["会用 C = Q/U 计算电容或电荷量","知道电容由电容器自身结构决定，与 Q、U 无关","能分析平行板电容器在『电压不变』和『电荷量不变』两种情形下 C、Q、U、E 的变化"],"dq":{"q":"某电容器所带电荷量为 4 μC 时，两极板间的电压为 20 V。它的电容是多少 μF？（只填数值）","a":"0.2"}},{"id":"cnp_h064","n":"实验：观察电容器的充、放电现象","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.4","d":"把电容器与电源、电阻、电流传感器连接，观察电容器充电、放电时电流和电压的变化。充放电的电流先大后小，I-t 图线与坐标轴所围的面积等于电容器所带电荷量，由 C = Q/U 可估算电容。","mc":["能描述电容器充电、放电过程中电流和电压的变化规律","会通过 I-t 图线下的面积（数格子）估算电荷量并求电容","能分析改变电阻等条件时 I-t 图线的变化"],"dq":{"q":"电容器通过电阻与恒压电源相连开始充电。关于充电过程，下列说法正确的是哪一个？","a":"充电电流由大变小，最后为零，电容器两极板间的电压增大到等于电源电压"}},{"id":"cnp_h065","n":"带电粒子在电场中的加速","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.5","d":"忽略重力时，带电粒子在电场中被加速，由动能定理 qU = ½mv² − ½mv₀² 求末速度或动能。该关系对匀强电场和非匀强电场都成立，只与电势差有关，与两极板间距无关。","mc":["会用动能定理 qU = ΔE_k 分析带电粒子在加速电场中的速度与动能","知道加速后的速度与 √(q/m) 成正比，能比较不同粒子的末速度","知道 qU = ΔE_k 与电场是否匀强无关"],"dq":{"q":"一个 α 粒子（电荷量为 2e）从静止开始，经 500 V 的电压加速后，获得的动能是多少 eV？（只填数值）","a":"1000"}},{"id":"cnp_h066","n":"带电粒子在电场中的偏转","g":"高3","sm":"上","ch":"必修三 第十章 静电场中的能量 10.5","d":"带电粒子垂直于电场方向射入匀强电场时，做类平抛运动：垂直电场方向匀速 x = v₀t，沿电场方向初速为零的匀加速 y = ½at²，a = qE/m = qU/(md)，偏转角满足 tanθ = v_y/v₀。","mc":["能把偏转运动分解为垂直电场方向的匀速运动和沿电场方向的匀加速运动","会计算偏移量 y 与偏转角的正切 tanθ","知道经同一加速电场加速后再偏转，偏移量与粒子的 q、m 无关"],"dq":{"q":"不计重力的带电粒子以初速度 v₀ 垂直射入匀强电场，粒子在电场中的轨迹是哪一个？","a":"抛物线"}},{"id":"cnp_h067","n":"电源和电流","g":"高3","sm":"上","ch":"必修三 第十一章 电路及其应用 11.1","d":"电荷的定向移动形成电流，电流 I = q/t；金属导体中电流的微观表达式 I = nqSv。规定正电荷定向移动的方向为电流方向；电源的作用是保持导体两端的电势差，使电路中有持续电流。","mc":["会用 I = q/t 计算电流，知道电流方向的规定","会用 I = nqSv 估算自由电子定向移动的速率","知道电源的作用，能处理正负电荷同时移动时的电流"],"dq":{"q":"30 s 内通过导体某一横截面的电荷量是 12 C，导体中的电流是多少 A？（只填数值）","a":"0.4"}},{"id":"cnp_h068","n":"欧姆定律与伏安特性曲线","g":"高3","sm":"上","ch":"必修三 第十一章 电路及其应用 11.2","d":"导体中的电流与导体两端的电压成正比，与导体的电阻成反比，I = U/R。线性元件的 I-U 图线是过原点的直线，非线性元件的图线是曲线，其每个状态的电阻仍为 R = U/I。欧姆定律适用于金属导电和电解质溶液。","mc":["会用 I = U/R 计算电流、电压和电阻","能读懂 I-U 图线，区分线性与非线性元件，会求某状态的电阻","知道欧姆定律的适用范围"],"dq":{"q":"某金属导体两端电压为 4 V 时，通过它的电流为 0.5 A。若温度不变，电压增大到 10 V，通过它的电流是多少 A？（只填数值）","a":"1.25"}},{"id":"cnp_h069","n":"电阻定律与电阻率","g":"高3","sm":"上","ch":"必修三 第十一章 电路及其应用 11.2","d":"导体的电阻与长度成正比，与横截面积成反比，R = ρ·l/S。电阻率 ρ 由材料本身性质决定，随温度变化，与导体的长度、横截面积无关。","mc":["会用 R = ρl/S 计算电阻","会分析导线对折、均匀拉长（体积不变）后的电阻变化","知道电阻率与电阻的区别，了解金属电阻率随温度升高而增大"],"dq":{"q":"铜的电阻率 ρ = 1.7×10⁻⁸ Ω·m。一根长 100 m、横截面积为 1.7 mm² 的铜导线，电阻是多少 Ω？（只填数值）","a":"1"}},{"id":"cnp_h070","n":"实验：长度的测量及其测量工具的选用","g":"高3","sm":"上","ch":"必修三 第十一章 电路及其应用 11.3","d":"游标卡尺用游标刻度与主尺刻度的差值读数：10 分度精度 0.1 mm，20 分度精度 0.05 mm，50 分度精度 0.02 mm，读数 = 主尺整毫米数 + 对齐格数 × 精度，不估读。螺旋测微器精度 0.01 mm，读数 = 固定刻度 + 可动刻度 × 0.01 mm，需估读一位。","mc":["会读 10、20、50 分度游标卡尺，读数以 mm 为单位且不估读","会读螺旋测微器，注意半毫米刻线和估读","能根据精度判断某个读数是否合理，并选用合适的测量工具"],"dq":{"q":"用 10 分度游标卡尺测一物体的长度，主尺上整毫米读数为 23 mm，游标上第 6 条刻线与主尺某刻线对齐。物体的长度是多少 mm？（只填数值）","a":"23.6"}},{"id":"cnp_h071","n":"实验：导体电阻率的测量","g":"高3","sm":"上","ch":"必修三 第十一章 电路及其应用 11.3","d":"测量金属丝电阻率的原理是 ρ = RS/l = πd²R/(4l)：用螺旋测微器测直径 d，用刻度尺测接入电路的有效长度 l，用伏安法测电阻 R。要掌握电流表内接、外接的选择及误差，控制电流减小温度对电阻率的影响。","mc":["能写出 ρ = πd²R/(4l) 并说明各量的测量方法","能选择电流表内接或外接，并判断测量值偏大还是偏小","知道减小误差的措施：多次测量取平均、通电时间短、电流不宜大"],"dq":{"q":"用伏安法测一阻值约为几欧的金属丝电阻，电流表内阻约 0.1 Ω，电压表内阻约几千欧。应采用哪种接法，测量值与真实值相比如何？","a":"电流表外接法，测量值偏小"}},{"id":"cnp_h072","n":"串联电路和并联电路","g":"高3","sm":"上","ch":"必修三 第十一章 电路及其应用 11.4","d":"串联电路中电流处处相等，总电压等于各部分电压之和，总电阻 R = R₁ + R₂ + …；并联电路中各支路电压相等，总电流等于各支路电流之和，1/R = 1/R₁ + 1/R₂ + …。并联总电阻小于任一支路电阻。","mc":["会计算串、并联电路的总电阻","会用电压、电流分配关系处理混联电路","知道并联电路中支路增多、总电阻减小，总电阻由小电阻主导"],"dq":{"q":"6 Ω 和 3 Ω 的两个电阻并联，总电阻是多少 Ω？（只填数值）","a":"2"}},{"id":"cnp_h073","n":"电表的改装","g":"高3","sm":"上","ch":"必修三 第十一章 电路及其应用 11.4","d":"小量程电流表（表头，满偏电流 I_g，内阻 R_g）串联分压电阻 R = U/I_g − R_g 可改装成电压表，并联分流电阻 R = I_gR_g/(I − I_g) 可改装成大量程电流表。改装后，电压表内阻变大，电流表内阻变小。","mc":["会计算改装电压表所需的串联电阻","会计算改装电流表所需的并联电阻","能分析改装后电表内阻变化，以及校准时读数偏大偏小的原因"],"dq":{"q":"满偏电流 I_g = 1 mA、内阻 R_g = 100 Ω 的表头，要改装成量程为 3 V 的电压表，需要串联的分压电阻是多少 Ω？（只填数值）","a":"2900"}},{"id":"cnp_h074","n":"实验：练习使用多用电表","g":"高3","sm":"上","ch":"必修三 第十一章 电路及其应用 11.5","d":"多用电表可测直流电压、直流电流和电阻。无论哪个挡位，电流都从红表笔流入、黑表笔流出。欧姆挡内部有电源，测量前要选择倍率并欧姆调零，读数 = 表盘读数 × 倍率；偏角过小则换大倍率，换挡后必须重新欧姆调零。","mc":["知道多用电表的红黑表笔与电流方向的关系","会使用欧姆挡：选倍率、欧姆调零、读数（表盘示数×倍率）","会根据指针偏角调整倍率，并能用 I = E/(R内 + Rx) 理解欧姆表的原理"],"dq":{"q":"关于多用电表红、黑表笔与电流方向的关系，下列说法正确的是哪一个？","a":"无论测电压、电流还是电阻，电流都从红表笔流入、黑表笔流出"}},{"id":"cnp_h075","n":"电功和电功率","g":"高3","sm":"上","ch":"必修三 第十二章 电能·能量守恒定律 12.1","d":"从静电力对电荷做功出发理解电功 W = UIt，知道电功率 P = UI 表示电流做功的快慢；会进行电能、电费的计算，并能用 kW·h 与 J 的换算处理实际问题。","mc":["会用 W = UIt 和 P = W/t = UI 计算电功和电功率","知道电功率描述做功的快慢而不是做功的多少","会计算用电器的耗电量和电费"],"dq":{"q":"某用电器两端的电压为 220 V，通过的电流为 0.5 A，工作 10 min，电流做的功是多少 J？（只填数值）","a":"66000"}},{"id":"cnp_h076","n":"焦耳定律","g":"高3","sm":"上","ch":"必修三 第十二章 电能·能量守恒定律 12.1","d":"知道电流通过导体产生的热量 Q = I²Rt（焦耳定律）；区分纯电阻电路与非纯电阻电路（如电动机），知道 UIt 是总电能，I²Rt 只是其中变成内能的部分。","mc":["会用 Q = I²Rt 计算热量和热功率","能区分纯电阻与非纯电阻电路中电功与电热的关系","会计算电动机的机械功率 P机 = UI − I²R"],"dq":{"q":"阻值为 10 Ω 的电阻通过 2 A 的电流，30 s 内产生的热量是多少 J？（只填数值）","a":"1200"}},{"id":"cnp_h077","n":"家庭电路与安全用电","g":"高3","sm":"上","ch":"必修三 第十二章 电能·能量守恒定律 12.1","d":"了解家庭电路由火线、零线、电能表、断路器（空气开关）、插座和用电器并联而成；会估算家庭电路的总功率和总电流，知道接地保护等安全用电措施。","mc":["知道家庭电路中各用电器并联及开关接在火线上","能解释短路和总功率过大使电流过大的原因","知道三孔插座接地线的保护作用，会估算断路器允许的总功率"],"dq":{"q":"家庭电路中，各用电器之间是怎样连接的？","a":"并联"}},{"id":"cnp_h078","n":"电动势","g":"高3","sm":"上","ch":"必修三 第十二章 电能·能量守恒定律 12.2","d":"知道电源通过非静电力做功把其他形式的能转化为电能，电动势 E = W非/q 描述电源这种转化本领的大小；区分电动势与路端电压，理解电源内阻。","mc":["理解电动势的物理意义和定义式 E = W/q","能区分电动势与路端电压","能用 W = EIt 计算电源提供的电能"],"dq":{"q":"关于电源的电动势，下列说法正确的是哪一个？","a":"表示电源把其他形式的能转化为电能的本领"}},{"id":"cnp_h079","n":"闭合电路的欧姆定律","g":"高3","sm":"上","ch":"必修三 第十二章 电能·能量守恒定律 12.2","d":"掌握闭合电路的欧姆定律 I = E/(R+r)，理解 E = U外 + U内 与能量守恒的关系；知道路端电压随外电阻变化的规律，以及开路和短路的特点。","mc":["会用 I = E/(R+r) 和 U = E − Ir 计算电流与路端电压","知道外电阻增大时路端电压增大，开路时 U = E","知道短路时电流 I = E/r，路端电压为零"],"dq":{"q":"电源电动势 E = 6 V，内阻 r = 1 Ω，外电路只有一个 R = 5 Ω 的电阻，电路中的电流是多少 A？（只填数值）","a":"1"}},{"id":"cnp_h080","n":"闭合电路的动态分析与功率","g":"高3","sm":"上","ch":"必修三 第十二章 电能·能量守恒定律 12.2","d":"会用“局部电阻 → 总电阻 → 总电流 → 路端电压 → 各部分”的程序分析闭合电路中电阻变化引起的动态问题；会计算电源的输出功率，知道外电阻等于内阻时输出功率最大。","mc":["会分析滑动变阻器阻值变化时电表示数的变化","知道 P出 = E²R/(R+r)²，R = r 时输出功率最大 E²/(4r)","会用“等效内阻”思想求可变电阻的最大功率"],"dq":{"q":"电源（电动势 E，内阻 r）、定值电阻 R₁、滑动变阻器 R₂ 串联，电流表串联在电路中，电压表测路端电压。当滑片移动使 R₂ 增大时，两表示数如何变化？","a":"电流表示数减小，电压表示数增大"}},{"id":"cnp_h081","n":"实验：电池电动势和内阻的测量","g":"高3","sm":"上","ch":"必修三 第十二章 电能·能量守恒定律 12.3","d":"利用 U = E − Ir，用电压表、电流表和滑动变阻器测量干电池的电动势和内阻；会用 U–I 图像的纵截距和斜率求 E 和 r，并分析电路接法带来的系统误差。","mc":["能画出测量电路并说明实验原理","会用 U–I 图像的截距和斜率求 E 与 r，注意坐标起点","能分析电压表分流造成的系统误差"],"dq":{"q":"测干电池电动势和内阻的实验中，由多组 (I, U) 数据作出 U–I 图线，图线的纵轴截距和斜率的绝对值分别表示什么？","a":"电动势 E；内阻 r"}},{"id":"cnp_h082","n":"能源与可持续发展","g":"高3","sm":"上","ch":"必修三 第十二章 电能·能量守恒定律 12.4","d":"知道能量守恒但能量转化具有方向性，耗散的内能难以再利用；了解水能、风能、太阳能、核能等的利用方式，区分可再生与不可再生能源，能做节能的简单估算。","mc":["能区分可再生能源和不可再生能源","能解释能量守恒与节约能源并不矛盾","会估算水力发电功率、节电量等实际问题"],"dq":{"q":"下列能源中属于可再生能源的是哪一个？","a":"水能"}},{"id":"cnp_h083","n":"磁场与磁感线","g":"高3","sm":"上","ch":"必修三 第十三章 电磁感应与电磁波初步 13.1","d":"知道磁体和电流周围存在磁场，磁场对磁极和电流有力的作用；用磁感线形象描述磁场，了解条形磁铁、蹄形磁铁的磁感线分布以及地磁场的特点。","mc":["知道磁场方向的规定","知道磁感线的特点：闭合曲线、不相交、疏密表示强弱","了解地磁场的分布，知道地磁两极与地理两极大致相反"],"dq":{"q":"物理学中规定，磁场中某点的磁场方向是下列哪一个方向？","a":"小磁针静止时 N 极所指的方向"}},{"id":"cnp_h084","n":"电流的磁场和安培定则","g":"高3","sm":"上","ch":"必修三 第十三章 电磁感应与电磁波初步 13.1","d":"知道奥斯特实验说明电流周围存在磁场，会用安培定则（右手螺旋定则）判断直线电流、环形电流和通电螺线管的磁场方向，并会叠加简单的磁场。","mc":["会用安培定则判断直线电流的磁场方向","会判断环形电流和通电螺线管内部的磁场及 N、S 极","会判断两根直线电流磁场的叠加方向"],"dq":{"q":"一根长直导线竖直放置，电流方向竖直向上。从上往下俯视，导线周围的磁感线方向是怎样的？","a":"逆时针方向的同心圆"}},{"id":"cnp_h085","n":"磁感应强度","g":"高3","sm":"上","ch":"必修三 第十三章 电磁感应与电磁波初步 13.2","d":"知道磁感应强度 B 是描述磁场强弱和方向的物理量，定义式 B = F/(IL)（导线垂直磁场），单位特斯拉（T）；知道 B 是矢量，由磁场本身决定，磁感应强度的叠加遵循平行四边形定则。","mc":["会用 B = F/(IL) 计算磁感应强度","理解 B 由磁场本身决定，与 F、I、L 无关，且 F = 0 不一定 B = 0","会对两个垂直磁场的磁感应强度做矢量合成"],"dq":{"q":"长 0.2 m 的直导线通有 5 A 的电流，垂直放在匀强磁场中，受到的磁场力为 0.1 N，磁场的磁感应强度是多少 T？（只填数值）","a":"0.1"}},{"id":"cnp_h086","n":"磁通量","g":"高3","sm":"上","ch":"必修三 第十三章 电磁感应与电磁波初步 13.2","d":"知道磁通量 Φ = BS 表示穿过某一面积的磁感线条数，单位韦伯（Wb）；当平面与磁场不垂直时 Φ = BS⊥，会计算磁通量及其变化，知道磁通量与线圈匝数无关。","mc":["会用 Φ = BS 计算垂直时的磁通量","会计算平面与磁场成夹角时的磁通量 Φ = BS sinθ","会计算线圈翻转时磁通量的变化量"],"dq":{"q":"匀强磁场的磁感应强度为 0.5 T，一个面积为 0.04 m² 的线圈平面与磁场垂直，穿过线圈的磁通量是多少 Wb？（只填数值）","a":"0.02"}},{"id":"cnp_h087","n":"电磁感应现象及应用","g":"高3","sm":"上","ch":"必修三 第十三章 电磁感应与电磁波初步 13.3","d":"知道法拉第发现电磁感应现象的探索过程；知道产生感应电流的条件是穿过闭合回路的磁通量发生变化；会判断各种情境下有无感应电流，了解电磁感应的应用。","mc":["能说出产生感应电流的条件","会用磁通量是否变化判断有无感应电流","能区分闭合回路与不闭合回路的情况"],"dq":{"q":"产生感应电流的条件是下列哪一个？","a":"穿过闭合回路的磁通量发生变化"}},{"id":"cnp_h088","n":"电磁波的发现及应用","g":"高3","sm":"上","ch":"必修三 第十三章 电磁感应与电磁波初步 13.4","d":"了解麦克斯韦预言电磁波、赫兹用实验证实电磁波的历史；知道电磁波在真空中以光速传播，c = λf；了解电磁波谱按波长的排列及无线电波、红外线、紫外线等的应用。","mc":["知道电磁波的预言和证实及电磁场的物质性","会用 c = λf 计算电磁波的波长或频率","能按波长排列电磁波谱并举例应用"],"dq":{"q":"首先用实验证实了电磁波存在的科学家是谁？","a":"赫兹"}},{"id":"cnp_h089","n":"能量量子化","g":"高3","sm":"上","ch":"必修三 第十三章 电磁感应与电磁波初步 13.5","d":"知道黑体辐射的实验规律，了解普朗克提出的能量子假设 ε = hν：物体辐射或吸收的能量只能是某一最小单位的整数倍；初步了解微观世界的量子化特征。","mc":["知道能量子 ε = hν 及普朗克常量的意义","知道黑体辐射强度随温度升高的变化规律","会用 ε = hν 估算光子的能量和光子数"],"dq":{"q":"普朗克提出的能量子假设认为，频率为 ν 的电磁辐射，其能量子的大小 ε 是多少（h 为普朗克常量）？","a":"hν"}},{"id":"cnp_h090","n":"动量","g":"高4","sm":"上","ch":"选必一 第一章 动量守恒定律 1.1","d":"动量是质量与速度的乘积，p = mv，是矢量，方向与速度方向相同，国际单位是 kg·m/s。动量的变化量 Δp = p′ − p 也是矢量，一维问题中要先规定正方向再代入正负号；动量与动能的联系是 Ek = p²/(2m)。","mc":["能写出动量的定义式并说出它是矢量","能在一维情形下规定正方向，计算动量及其变化量","能区分动量与动能，会用 Ek = p²/(2m) 比较"],"dq":{"q":"关于动量，下列说法正确的是哪一个？","a":"动量是矢量，方向与物体速度的方向相同"}},{"id":"cnp_h091","n":"冲量","g":"高4","sm":"上","ch":"选必一 第一章 动量守恒定律 1.2","d":"冲量是力与力的作用时间的乘积，I = Ft，是矢量，恒力冲量的方向与力的方向相同，单位 N·s。冲量描述力对时间的累积效应，与物体是否运动无关；F-t 图像与时间轴所围面积表示冲量。","mc":["能写出恒力冲量 I = Ft 并判断其方向","知道物体静止时力也有冲量","能用 F-t 图像的面积求冲量，会求合外力的冲量"],"dq":{"q":"关于冲量，下列说法正确的是哪一个？","a":"冲量是矢量，恒力冲量的方向与该力的方向相同"}},{"id":"cnp_h092","n":"动量定理","g":"高4","sm":"上","ch":"选必一 第一章 动量守恒定律 1.2","d":"动量定理：物体所受合外力的冲量等于物体动量的变化量，I合 = Δp，即 F合 t = mv′ − mv，是矢量式，一维问题中要规定正方向。能解释缓冲、冲击等现象：动量变化相同，作用时间越长平均作用力越小。","mc":["能写出动量定理并说明冲量必须是合外力的冲量","会在一维情形下用动量定理求速度或平均作用力","能用动量定理解释缓冲与冲击现象"],"dq":{"q":"关于动量定理，下列表述正确的是哪一个？","a":"物体所受合外力的冲量等于物体动量的变化量"}},{"id":"cnp_h093","n":"动量守恒定律","g":"高4","sm":"上","ch":"选必一 第一章 动量守恒定律 1.3","d":"如果一个系统不受外力，或者所受外力的矢量和为零，这个系统的总动量保持不变。内力远大于外力的短暂过程（如碰撞、爆炸）也可近似认为动量守恒。应用时要选定系统、判断条件、规定正方向，用 m1v1 + m2v2 = m1v1′ + m2v2′ 求解。","mc":["能判断一个系统在某过程中动量是否守恒","会选正方向列动量守恒方程求未知速度","知道动量守恒定律的普适性，与机械能是否守恒无关"],"dq":{"q":"动量守恒定律成立的条件是什么？","a":"系统不受外力，或所受外力的矢量和为零"}},{"id":"cnp_h094","n":"实验：验证动量守恒定律","g":"高4","sm":"上","ch":"选必一 第一章 动量守恒定律 1.4","d":"通过气垫导轨加光电门，或斜槽加平抛小球等方案验证动量守恒定律。关键是保证系统合外力近似为零（导轨水平、斜槽末端水平），测出质量和碰撞前后的速度（或能代替速度的量），比较 m1v1 + m2v2 与 m1v1′ + m2v2′。","mc":["能说明气垫导轨方案中导轨需调水平的原因，会由挡光片宽度和挡光时间算速度","能说明平抛方案中用水平位移代替速度的原理并写出验证式","会处理实验数据并判断动量是否守恒"],"dq":{"q":"用气垫导轨和光电门验证动量守恒定律时，实验前要把导轨调成水平，主要目的是什么？","a":"使滑块在水平方向所受合外力近似为零，保证两滑块组成的系统动量守恒"}},{"id":"cnp_h095","n":"弹性碰撞和非弹性碰撞","g":"高4","sm":"上","ch":"选必一 第一章 动量守恒定律 1.5","d":"碰撞过程时间极短，内力远大于外力，系统动量守恒。按动能是否损失分为：弹性碰撞（动能不变）、非弹性碰撞（动能减少）和完全非弹性碰撞（碰后粘在一起共速，动能损失最多）。","mc":["能区分弹性碰撞、非弹性碰撞和完全非弹性碰撞","知道各类碰撞中动量都守恒，动能不会增加","能计算碰撞过程损失的动能"],"dq":{"q":"关于碰撞，下列说法正确的是哪一个？","a":"弹性碰撞前后系统的总动能不变"}},{"id":"cnp_h096","n":"碰撞问题的分析","g":"高4","sm":"上","ch":"选必一 第一章 动量守恒定律 1.5","d":"一维弹性碰撞：m1 以 v1 碰静止的 m2，v1′ = (m1 − m2)v1/(m1 + m2)，v2′ = 2m1v1/(m1 + m2)；质量相等则交换速度。完全非弹性碰撞动能损失最多。判断一个碰撞结果是否可能，要同时检验动量守恒、动能不增加和碰后速度合理。","mc":["会用一维弹性碰撞公式求碰后速度并讨论质量关系","知道完全非弹性碰撞损失动能最多，会判断碰撞结果是否可能","能综合动量、能量和运动情况分析碰撞问题"],"dq":{"q":"质量均为 2 kg 的两个小球在光滑水平面上发生弹性正碰，碰前一个以 4 m/s 的速度运动，另一个静止，碰后原来静止的小球的速度是多少 m/s？（只填数值）","a":"4"}},{"id":"cnp_h097","n":"反冲现象与火箭","g":"高4","sm":"上","ch":"选必一 第一章 动量守恒定律 1.6","d":"一个静止的物体向某一方向抛出一部分时，剩余部分会向相反方向运动，这就是反冲，其依据是动量守恒定律。火箭靠向后高速喷出气体获得前进的速度，在真空中也能飞行；喷气速度越大、质量比越大，火箭获得的速度越大。","mc":["能识别反冲现象并用动量守恒求反冲速度","能求火箭喷气过程中火箭获得的速度","能说明火箭的工作原理"],"dq":{"q":"下列现象中，属于反冲现象的是哪一个？","a":"火箭向后喷出高速气体而向前飞行"}},{"id":"cnp_h098","n":"简谐运动","g":"高4","sm":"上","ch":"选必一 第二章 机械振动 2.1","d":"物体在平衡位置附近做往复运动叫机械振动。弹簧振子是理想化模型，其位移是相对平衡位置的位移；回复力总指向平衡位置，位移越大加速度越大，位移时间图像是正弦（或余弦）曲线的运动叫简谐运动，运动具有对称性。","mc":["能说出弹簧振子的位移是相对平衡位置的位移，并区分平衡位置与弹簧原长位置","能分析振子在最大位移处、平衡位置处的位移、速度、加速度","知道简谐运动的位移时间图像是正弦曲线"],"dq":{"q":"弹簧振子做简谐运动时，它的位移是指什么？","a":"相对平衡位置的位移，由平衡位置指向振子所在位置"}},{"id":"cnp_h099","n":"简谐运动的描述","g":"高4","sm":"上","ch":"选必一 第二章 机械振动 2.2","d":"描述简谐运动的物理量有振幅 A、周期 T、频率 f = 1/T 和相位。位移可写成 x = A sin(ωt + φ)，其中 ω = 2π/T = 2πf，ωt + φ 叫相位，φ 是初相位。一个周期内振子通过的路程为 4A。","mc":["能说出振幅、周期、频率、相位的含义，知道 ω = 2π/T","能由 x = A sin(ωt + φ) 读出振幅、周期、初相并计算某时刻的位移","能比较两个简谐运动的频率与相位差"],"dq":{"q":"关于简谐运动的振幅，下列说法正确的是哪一个？","a":"振幅是标量，等于振子离开平衡位置的最大距离"}},{"id":"cnp_h100","n":"简谐运动的回复力和能量","g":"高4","sm":"上","ch":"选必一 第二章 机械振动 2.3","d":"简谐运动的回复力 F = −kx，大小与位移成正比、方向总指向平衡位置。振动过程中动能与势能相互转化，没有能量损失时总机械能不变，E = ½kA²，振幅越大能量越大；弹簧振子的周期 T = 2π√(m/k)，与振幅无关。","mc":["能说明 F = −kx 中负号的含义并计算回复力","能用能量守恒分析动能、势能的转化并计算平衡位置的最大速度","知道总能量与振幅的关系，周期与振幅无关"],"dq":{"q":"简谐运动的回复力 F = −kx，式中负号表示什么？","a":"回复力的方向总是与位移方向相反，指向平衡位置"}},{"id":"cnp_h101","n":"单摆","g":"高4","sm":"上","ch":"选必一 第二章 机械振动 2.4","d":"摆角很小时（一般小于 5°），单摆的回复力近似为 F = −(mg/l)x，摆球做简谐运动，周期 T = 2π√(l/g)，与摆球质量、振幅无关，由摆长 l 和当地重力加速度 g 决定。","mc":["知道单摆做简谐运动的条件和回复力的来源","会用 T = 2π√(l/g) 计算周期，比较不同条件下周期的变化","知道单摆周期与摆球质量、振幅无关"],"dq":{"q":"摆长为 1.00 m 的单摆在摆角很小时摆动，当地重力加速度 g = 10 m/s²，取 π² = 10，它的周期是多少 s？（只填数值）","a":"2"}},{"id":"cnp_h102","n":"实验：用单摆测量重力加速度","g":"高4","sm":"上","ch":"选必一 第二章 机械振动 2.5","d":"用单摆测重力加速度：由 T = 2π√(l/g) 得 g = 4π²l/T²，或作 T²–l 图像，斜率 k = 4π²/g，g = 4π²/k。要点是摆长 = 摆线长 + 摆球半径，摆角小于 5°，从最低点开始计时并测多次全振动的总时间求周期。","mc":["会正确测量摆长与周期","会由 T²–l 图像的斜率求重力加速度","能分析摆长测量错误对图像和结果的影响"],"dq":{"q":"用单摆测重力加速度时，摆长应怎样测量？","a":"摆线长度加上摆球的半径"}},{"id":"cnp_h103","n":"受迫振动与共振","g":"高4","sm":"上","ch":"选必一 第二章 机械振动 2.6","d":"实际振动因阻力而振幅逐渐减小，叫阻尼振动。系统在周期性驱动力作用下的振动叫受迫振动，稳定后其频率等于驱动力的频率，与固有频率无关。驱动力频率等于系统固有频率时，振幅最大，叫共振。","mc":["能区分固有频率、驱动力频率和受迫振动的频率","能说出共振曲线的特点和共振的条件","能用共振条件解决简单的实际问题并说出其利用与防止"],"dq":{"q":"物体在周期性驱动力作用下做受迫振动，稳定后它的振动频率等于什么？","a":"驱动力的频率"}},{"id":"cnp_h104","n":"波的形成","g":"高4","sm":"上","ch":"选必一 第三章 机械波 3.1","d":"机械波是机械振动在介质中的传播。波传播的是振动形式和能量，介质中的质点只在各自平衡位置附近振动，并不随波迁移；按质点振动方向与波传播方向的关系，波分为横波和纵波，并且各质点的起振方向都与波源的起振方向相同。","mc":["能说明机械波的形成条件和波传播的本质（振动形式与能量，而非质点迁移）","能区分横波与纵波，并举出实例","能判断介质中各质点起振的先后和起振方向"],"dq":{"q":"机械波在介质中传播时，介质中的质点是怎样运动的？","a":"只在各自的平衡位置附近振动，不随波迁移"}},{"id":"cnp_h105","n":"波的描述","g":"高4","sm":"上","ch":"选必一 第三章 机械波 3.2","d":"描述波的物理量有波长、频率（周期）和波速：一个周期内波传播一个波长，波速 v = λ/T = λf。频率由波源决定，波速由介质决定，所以波进入另一种介质时频率不变，波速和波长改变。","mc":["能说出波长、频率、周期、波速的含义，并用 v = λf 进行计算","知道波的频率由波源决定、波速由介质决定","能判断波从一种介质进入另一种介质时各物理量的变化"],"dq":{"q":"一列波的波长为 2 m，频率为 5 Hz，它的传播速度是多少？","a":"10 m/s"}},{"id":"cnp_h106","n":"波的图像与振动图像","g":"高4","sm":"上","ch":"选必一 第三章 机械波 3.2","d":"波的图像表示某一时刻介质中各质点相对平衡位置的位移，振动图像表示某一质点位移随时间的变化。由波的图像和传播方向可以判断质点的振动方向（上下坡法、同侧法），也可以反过来由质点的振动方向判断波的传播方向。","mc":["能区分波的图像与振动图像的横、纵坐标及物理意义","能用上下坡法或同侧法判断质点的振动方向与波的传播方向","能结合两种图像读出波长、周期并求波速"],"dq":{"q":"关于波的图像与某质点的振动图像，下列说法正确的是哪一个？","a":"波的图像描述某一时刻各质点的位移，振动图像描述某一质点的位移随时间的变化"}},{"id":"cnp_h107","n":"波的反射、折射和衍射","g":"高4","sm":"上","ch":"选必一 第三章 机械波 3.3","d":"波在传播中遇到障碍物或界面会发生反射，从一种介质进入另一种介质会发生折射，遇到尺寸与波长相差不多或比波长小的障碍物或孔时会发生明显的衍射。反射时波速、频率、波长不变；折射时频率不变，波速和波长改变。","mc":["能说明波的反射、折射、衍射现象及其条件","能判断反射、折射时波速、频率、波长的变化","能用波的反射（回声）进行简单计算"],"dq":{"q":"波长为 2 m 的水波通过下列宽度的狭缝，衍射现象最明显的是哪一个？","a":"1.5 m"}},{"id":"cnp_h108","n":"波的干涉","g":"高4","sm":"上","ch":"选必一 第三章 机械波 3.4","d":"两列频率相同、振动方向相同、相位差恒定的波相遇，会形成稳定的干涉图样：某些区域振动始终加强，某些区域始终减弱。两波源同相时，路程差 Δr = nλ 的点加强，Δr = (n + ½)λ 的点减弱；振动加强点只是振幅最大，并非位移始终最大。","mc":["能说出稳定干涉的条件","能用路程差与波长的关系判断同相（或反相）波源的加强点与减弱点","能纠正“加强点位移始终最大”等误区"],"dq":{"q":"两列波发生稳定干涉的必要条件是什么？","a":"频率相同、振动方向相同、相位差恒定"}},{"id":"cnp_h109","n":"多普勒效应","g":"高4","sm":"上","ch":"选必一 第三章 机械波 3.5","d":"波源与观察者相互靠近时，观察者接收到的频率比波源的频率高；相互远离时，接收到的频率比波源的频率低，这种现象叫多普勒效应。它是接收频率的变化，波源本身的频率并不改变，各种波都能产生这种效应，可用于测速等。","mc":["能说出多普勒效应的内容，判断接收频率的升高或降低","能从单位时间内接收到的完整波的个数解释多普勒效应","能举例说明多普勒效应的应用"],"dq":{"q":"声源与观察者相互靠近时，观察者接收到的声音频率与声源本身的频率相比有什么关系？","a":"大于声源的频率"}},{"id":"cnp_h110","n":"光的折射","g":"高4","sm":"上","ch":"选必一 第四章 光 4.1","d":"光从一种介质斜射入另一种介质时传播方向改变，入射角 i 的正弦与折射角 r 的正弦之比为定值，叫介质的折射率，n = sin i / sin r。折射率还等于光在真空中的速度与介质中速度之比 n = c/v，光进入介质时频率不变，波长变为真空中的 1/n。","mc":["能用折射定律 n = sin i / sin r 进行计算，知道 i、r 是与法线的夹角","能用 n = c/v 求光在介质中的速度，知道折射率都大于 1","能说明光进入介质时频率不变，波长变短"],"dq":{"q":"折射率的定义式 n = sin i / sin r 中，i 和 r 分别是什么？","a":"入射光线、折射光线与法线的夹角"}},{"id":"cnp_h111","n":"实验：测量玻璃的折射率","g":"高4","sm":"上","ch":"选必一 第四章 光 4.1","d":"用插针法测玻璃砖的折射率：在玻璃砖一侧插 P₁、P₂ 确定入射光线，在另一侧插 P₃、P₄ 使其挡住 P₁、P₂ 的像，确定出射光线，连出折射光线后量出入射角与折射角，用 n = sin i / sin r 计算，也可以用作圆的方法。","mc":["能说明插针法的操作要点和注意事项","能用作图法（作圆、量取线段长度之比）求折射率","能分析玻璃砖界面画偏等引起的误差"],"dq":{"q":"插针法测玻璃折射率时，确定出射光线需要怎样插 P₃、P₄？","a":"P₃ 挡住 P₁、P₂ 的像，P₄ 挡住 P₃ 以及 P₁、P₂ 的像"}},{"id":"cnp_h112","n":"全反射","g":"高4","sm":"上","ch":"选必一 第四章 光 4.2","d":"光从光密介质射入光疏介质时，折射角大于入射角；当入射角增大到临界角 C 时，折射光完全消失，只剩反射光，这就是全反射，sinC = 1/n。发生全反射的条件是光从光密介质射向光疏介质，且入射角大于或等于临界角，光导纤维利用的就是全反射。","mc":["能说出发生全反射的条件，会判断是否可能发生全反射","能用 sinC = 1/n 求临界角，并解决水下光源等问题","知道光导纤维的结构（内芯折射率大于外套）和原理"],"dq":{"q":"光发生全反射的条件是哪一个？","a":"光从光密介质射向光疏介质，且入射角大于或等于临界角"}},{"id":"cnp_h113","n":"光的干涉","g":"高4","sm":"上","ch":"选必一 第四章 光 4.3","d":"光通过双缝后形成两束相干光，在屏上叠加形成明暗相间的干涉条纹：到两缝路程差为波长整数倍处是亮条纹，为半波长奇数倍处是暗条纹，相邻条纹间距 Δx = lλ/d。条纹间距与波长成正比、与双缝间距成反比；白光的干涉条纹是彩色的。","mc":["能说明双缝干涉的原理和亮、暗条纹的条件","能用 Δx = lλ/d 计算条纹间距，并分析各因素的影响","能说明干涉现象说明光具有波动性"],"dq":{"q":"杨氏双缝干涉实验中，在光源后放置双缝的目的是什么？","a":"使一束光分成频率相同、相位差恒定的两列光"}},{"id":"cnp_h114","n":"实验：用双缝干涉测量光的波长","g":"高4","sm":"上","ch":"选必一 第四章 光 4.4","d":"用双缝干涉测光的波长：光源、滤光片、单缝、双缝、遮光筒、屏依次排列，测出 n 条亮条纹中心的距离得到 Δx = (aₙ − a₁)/(n − 1)，再由 λ = Δx·d/l 算出波长。数据处理时要注意把 mm、m、nm 的单位统一，并分清条纹数与间隔数。","mc":["能说出器材的排列顺序和各元件的作用","能由测量头读数求出 Δx，并用 λ = Δx·d/l 计算波长","能分析条纹数与间隔数混淆等误差"],"dq":{"q":"双缝干涉测波长的实验装置中，光具座上各元件从光源一侧开始的正确排列顺序是什么？","a":"光源、滤光片、单缝、双缝、遮光筒、屏"}},{"id":"cnp_h115","n":"光的衍射","g":"高4","sm":"上","ch":"选必一 第四章 光 4.5","d":"光能绕过障碍物传播的现象叫光的衍射。当孔或障碍物的尺寸跟光的波长相差不多或比光的波长小时，衍射明显。单缝衍射条纹中央亮条纹最宽最亮、两侧条纹较窄较暗；圆盘衍射阴影中心的泊松亮斑是光的波动性的有力证据。","mc":["能说出光发生明显衍射的条件","能区分单缝衍射条纹与双缝干涉条纹的特点","能说明泊松亮斑等现象说明光具有波动性"],"dq":{"q":"光能发生明显衍射现象的条件是什么？","a":"障碍物或孔的尺寸跟光的波长相差不多或比波长小"}},{"id":"cnp_h116","n":"光的偏振","g":"高4","sm":"上","ch":"选必一 第四章 光 4.6","d":"自然光在垂直于传播方向的各个方向上振动强度相同，偏振光只沿某一特定方向振动。光能发生偏振，说明光是横波。两块偏振片透振方向平行时透光最强，垂直时几乎不透光，偏振现象在摄影、立体电影等中有应用。","mc":["能说明光的偏振现象并由此说明光是横波","能判断两偏振片透振方向变化时透射光强的变化","能举例说明偏振现象的应用"],"dq":{"q":"光能发生偏振现象，说明光是什么？","a":"横波"}},{"id":"cnp_h117","n":"激光","g":"高4","sm":"上","ch":"选必一 第四章 光 4.6","d":"激光是人工产生的光，具有相干性好、平行度好、亮度高的特点。利用相干性可做全息照相和光纤通信的载体，利用平行度可做精确测距，利用高亮度（能量集中）可做切割、焊接和手术。","mc":["能说出激光的特点","能把激光的应用与对应的特点联系起来","能进行激光测距、功率等简单计算"],"dq":{"q":"激光与普通光源发出的光相比，主要特点是什么？","a":"相干性好、平行度好、亮度高"}},{"id":"cnp_h118","n":"安培力","g":"高5","sm":"上","ch":"选必二 第一章 安培力与洛伦兹力 1.1","d":"通电导线在磁场中受到安培力。大小 F = BIL sinθ（θ 为电流方向与磁场方向的夹角），电流与磁场平行时为零，垂直时最大；方向用左手定则判定，总垂直于电流方向和磁场方向所在的平面。","mc":["会用 F = BIL sinθ 计算安培力大小，会求弯折导线的等效长度","会用左手定则判断安培力的方向","知道安培力方向与电流、磁场方向的空间关系"],"dq":{"q":"一段长 0.6 m 的直导线通有 4 A 的电流，放在磁感应强度为 0.5 T 的匀强磁场中，导线与磁场方向夹角为 30°。导线受到的安培力大小是多少 N？（sin30° = 0.5，只填数值）","a":"0.6"}},{"id":"cnp_h119","n":"磁电式电表与安培力的应用","g":"高5","sm":"上","ch":"选必二 第一章 安培力与洛伦兹力 1.1","d":"磁电式电表中，蹄形磁铁和铁芯间有辐向均匀磁场，线圈平面总与磁感线平行，安培力矩与电流成正比；螺旋弹簧的反向力矩与偏角成正比，所以指针偏角与电流成正比，刻度盘均匀。","mc":["说明辐向磁场使刻度均匀的原因","会用偏角与电流成正比做计算","知道电流反向时指针反向偏转、短接可使指针运输时少摆动"],"dq":{"q":"磁电式电流表的蹄形磁铁与铁芯之间是辐向均匀分布的磁场，这样设计的主要作用是什么？","a":"线圈平面总与磁感线平行，安培力矩只与电流大小成正比"}},{"id":"cnp_h120","n":"洛伦兹力","g":"高5","sm":"上","ch":"选必二 第一章 安培力与洛伦兹力 1.2","d":"磁场对运动电荷的作用力叫洛伦兹力，大小 f = qvB（v 垂直于 B），v 平行于 B 时为零；方向用左手定则，四指指向正电荷运动方向（负电荷则指向相反），洛伦兹力总垂直于速度，永不做功。","mc":["会用 f = qvB 计算洛伦兹力","会判断正负电荷所受洛伦兹力的方向","知道洛伦兹力永不做功，只改变速度方向"],"dq":{"q":"电荷量为 5×10⁻⁶ C 的带电粒子以 400 m/s 的速度垂直射入磁感应强度为 0.5 T 的匀强磁场，所受洛伦兹力大小是多少 N？（只填数值）","a":"0.001"}},{"id":"cnp_h121","n":"带电粒子在匀强磁场中的运动","g":"高5","sm":"上","ch":"选必二 第一章 安培力与洛伦兹力 1.3","d":"带电粒子垂直射入匀强磁场，只受洛伦兹力时做匀速圆周运动。由 qvB = mv²/r 得 r = mv/(qB)，周期 T = 2πm/(qB)，周期与速度、半径无关。能确定圆心、半径并求出时间、位置。","mc":["会用 r = mv/(qB) 和 T = 2πm/(qB) 计算半径和周期","知道周期只与荷质比和磁感应强度有关","会在边界入射问题中根据几何关系确定出射点"],"dq":{"q":"一个质量为 6.4×10⁻²⁷ kg、电荷量为 3.2×10⁻¹⁹ C 的粒子，以 5×10⁵ m/s 的速度垂直射入磁感应强度为 0.1 T 的匀强磁场，它做圆周运动的半径是多少 m？（只填数值）","a":"0.1"}},{"id":"cnp_h122","n":"质谱仪","g":"高5","sm":"上","ch":"选必二 第一章 安培力与洛伦兹力 1.4","d":"质谱仪先用电场加速离子：qU = mv²/2，再让离子在匀强磁场中偏转，半径 r = (1/B)√(2mU/q)；根据落点位置可以测出荷质比、区分同位素。离子经速度选择器时满足 qE = qvB，即 v = E/B。","mc":["会由 qU = mv²/2 求加速后的速度","会由半径比较离子的质量或荷质比","知道速度选择器的条件 v = E/B 与电荷量、电性无关"],"dq":{"q":"某离子的比荷 q/m = 4×10⁷ C/kg，由静止经 500 V 的电压加速，射出时速度是多少 m/s？（只填数值）","a":"200000"}},{"id":"cnp_h123","n":"回旋加速器","g":"高5","sm":"上","ch":"选必二 第一章 安培力与洛伦兹力 1.4","d":"回旋加速器中，粒子在 D 形盒内的磁场里做圆周运动，每次通过狭缝被电场加速。交变电压的周期必须等于粒子回旋周期 T = 2πm/(qB)；粒子最大动能 Ekm = q²B²R²/(2m) 由 D 形盒半径 R 决定，与加速电压无关。","mc":["知道交变电压周期等于粒子回旋周期","会用 Ekm = q²B²R²/(2m) 判断最大动能的影响因素","会由总动能和每次加速增益计算加速次数和圈数"],"dq":{"q":"回旋加速器中，要使粒子每次通过狭缝时都被加速，所加交变电压的周期应满足什么条件？","a":"等于粒子在磁场中做圆周运动的周期"}},{"id":"cnp_h124","n":"实验：探究影响感应电流方向的因素","g":"高5","sm":"上","ch":"选必二 第二章 电磁感应 2.1","d":"用条形磁铁插入、拔出线圈，观察电流表指针偏转，探究感应电流方向与磁铁运动、磁场方向的关系。实验前先用已知方向的电流（带保护电阻的干电池试触）确定指针偏转方向与电流方向的对应关系。","mc":["知道实验前要先确定指针偏转与电流方向的对应关系","会根据磁铁极性与运动方向分析磁通量变化和感应磁场方向","能从实验现象归纳出感应电流方向的规律"],"dq":{"q":"探究感应电流方向的实验中，正式把磁铁插入线圈之前，要先用干电池（串联保护电阻）试触电流表。这样做的目的是什么？","a":"确定指针偏转方向与电流方向的对应关系"}},{"id":"cnp_h125","n":"楞次定律","g":"高5","sm":"上","ch":"选必二 第二章 电磁感应 2.1","d":"感应电流具有这样的方向：感应电流的磁场总要阻碍引起感应电流的磁通量的变化。“阻碍”是使变化变慢，不是阻止，也不是简单的“相反”：磁通量增加时（增反）感应磁场与原磁场相反，磁通量减少时（减同）则相同。","mc":["会用楞次定律结合安培定则判断感应电流方向","理解“阻碍”不是“阻止”，也不是“相反”","会用来拒去留、增缩减扩分析导体的运动趋势"],"dq":{"q":"关于楞次定律中的“阻碍”，下列说法正确的是哪一个？","a":"感应电流的磁场阻碍的是引起感应电流的磁通量的变化"}},{"id":"cnp_h126","n":"法拉第电磁感应定律","g":"高5","sm":"上","ch":"选必二 第二章 电磁感应 2.2","d":"闭合电路中感应电动势的大小，跟穿过这一电路的磁通量的变化率成正比，E = nΔΦ/Δt。E 的大小取决于 ΔΦ/Δt（Φ-t 图像的斜率），与 Φ 本身及 ΔΦ 的大小无关。当 B 均匀变化而面积不变时 E = nSΔB/Δt。","mc":["会用 E = nΔΦ/Δt 计算感应电动势","知道 E 取决于磁通量变化率而非 Φ 或 ΔΦ","会由 Φ-t 图像或 B-t 图像比较电动势大小"],"dq":{"q":"一个 50 匝的线圈，穿过它的磁通量在 0.2 s 内由 0.01 Wb 均匀增加到 0.05 Wb，线圈中感应电动势的大小是多少 V？（只填数值）","a":"10"}},{"id":"cnp_h127","n":"导体切割磁感线时的感应电动势","g":"高5","sm":"上","ch":"选必二 第二章 电磁感应 2.2","d":"导体棒在匀强磁场中垂直切割磁感线时 E = BLv；速度 v 与磁感应强度 B 夹角为 θ 时 E = BLv sinθ。方向用右手定则，在做电源的导体内部电流从低电势流向高电势。棒绕一端匀速转动时 E = BL²ω/2。","mc":["会用 E = BLv 与 E = BLv sinθ 计算","会用右手定则判断电流方向和两端电势高低","会计算绕端点转动的导体棒的感应电动势"],"dq":{"q":"长 0.4 m 的导体棒在磁感应强度为 0.5 T 的匀强磁场中，以 10 m/s 的速度垂直于磁感线、垂直于棒的方向匀速运动，棒两端的感应电动势是多少 V？（只填数值）","a":"2"}},{"id":"cnp_h128","n":"电磁感应中的电路、能量与动力学问题","g":"高5","sm":"上","ch":"选必二 第二章 电磁感应 2.2","d":"把切割磁感线的导体看成电源（E、内阻 r），按闭合电路欧姆定律分析电流与路端电压；安培力做负功，其他能量转化为电能，再转化为焦耳热；受力平衡 F = B²L²v/R总 时棒达到收尾速度；通过回路的电荷量 q = nΔΦ/R总。","mc":["会把切割导体当电源分析电路，区分电动势与路端电压","会用牛顿运动定律和平衡条件求收尾速度","会用功能关系和 q = ΔΦ/R总 分析能量与电荷量"],"dq":{"q":"水平光滑平行导轨间距 0.5 m，左端接 1.5 Ω 的电阻 R，垂直导轨的金属棒 ab 电阻为 0.5 Ω，匀强磁场 B = 0.8 T 垂直于导轨平面。棒以 5 m/s 的速度匀速向右运动，a、b 两端的电压是多少 V？（导轨电阻不计，只填数值）","a":"1.5"}},{"id":"cnp_h129","n":"涡流、电磁阻尼和电磁驱动","g":"高5","sm":"上","ch":"选必二 第二章 电磁感应 2.3","d":"块状金属处在变化的磁场中或在磁场中运动时，内部产生旋涡状的感应电流，叫涡流。涡流受安培力阻碍相对运动，形成电磁阻尼；磁场运动带动导体运动，形成电磁驱动。可以利用涡流加热（电磁炉、真空冶炼），也要防止其发热（硅钢片叠成铁芯）。","mc":["知道涡流的成因","会解释电磁阻尼与电磁驱动现象","能区分涡流的利用与防止"],"dq":{"q":"涡流是指什么？","a":"块状金属在变化磁场中或在磁场中运动时，内部产生的旋涡状感应电流"}},{"id":"cnp_h130","n":"互感和自感","g":"高5","sm":"上","ch":"选必二 第二章 电磁感应 2.4","d":"线圈中电流变化时，自身产生感应电动势，叫自感，E = LΔI/Δt，方向总是阻碍电流的变化（不是阻止）。通电时电流缓慢增大；断电时线圈相当于电源，让电流缓慢减小。互感是两个相邻线圈间，一个线圈中变化的电流通过变化的磁场使另一个线圈产生感应电动势，不需要导线连接，变压器就是利用互感工作的。","mc":["理解自感电动势阻碍电流变化而不是阻止，知道互感现象及其应用","会分析通电、断电时灯泡的亮暗变化及闪亮条件","会用 E = LΔI/Δt 计算自感电动势"],"dq":{"q":"关于自感现象和互感现象，下列说法正确的是哪一个？","a":"自感电动势阻碍线圈自身电流的变化；互感使相邻的另一个线圈中产生感应电动势"}},{"id":"cnp_h131","n":"交变电流的产生","g":"高5","sm":"上","ch":"选必二 第三章 交变电流 3.1","d":"矩形线圈在匀强磁场中绕垂直于磁场的轴匀速转动，会产生按正弦规律变化的感应电动势。学习中性面的特点、从中性面开始计时的瞬时值表达式 e = Em sinωt，以及峰值 Em = NBSω。","mc":["能说出中性面处磁通量、感应电动势、电流方向的特点","会写从中性面开始计时的 e = Em sinωt 并计算瞬时值","会用 Em = NBSω 计算峰值并分析转速变化的影响"],"dq":{"q":"矩形线圈在匀强磁场中绕垂直于磁场的轴匀速转动。线圈转到中性面位置（线圈平面与磁场垂直）时，下列说法正确的是哪一个？","a":"磁通量最大，感应电动势为零，电流方向在此位置改变"}},{"id":"cnp_h132","n":"交变电流的描述","g":"高5","sm":"上","ch":"选必二 第三章 交变电流 3.2","d":"用周期、频率、峰值和有效值描述交变电流。有效值是按热效应等效的直流值，正弦式交变电流 E = Em/√2；非正弦交变电流的有效值要按一个周期内的热效应来计算，不能用平均值代替。","mc":["能由 e = Em sinωt 读出峰值、周期和频率","知道正弦式交变电流有效值与峰值的 √2 关系","会按热效应求非正弦交变电流的有效值"],"dq":{"q":"某正弦式交变电动势的瞬时值表达式为 e = 10√2 sin(100πt) V，它的有效值是多少？","a":"10 V"}},{"id":"cnp_h133","n":"变压器","g":"高5","sm":"上","ch":"选必二 第三章 交变电流 3.3","d":"变压器利用互感现象改变交流电压。理想变压器没有能量损失，原、副线圈电压之比等于匝数之比，电流与匝数成反比，输入功率等于输出功率；变压器不能改变直流电压，也不能改变交流电的频率。","mc":["会用 U1/U2 = n1/n2 和 I1/I2 = n2/n1 计算","知道变压器只对交变电流起作用，不改变频率和功率","能分析负载变化时原、副线圈各量的变化"],"dq":{"q":"理想变压器的原线圈匝数 n1 = 1100，副线圈匝数 n2 = 60，原线圈接 220 V 交流电，求副线圈两端的电压（单位 V，只填数值）。","a":"12"}},{"id":"cnp_h134","n":"实验：探究变压器原、副线圈电压与匝数的关系","g":"高5","sm":"上","ch":"选必二 第三章 交变电流 3.3","d":"用可拆变压器、低压交流电源和交流电压表，探究原、副线圈电压与匝数的关系。用控制变量法分别改变匝数，记录电压，比较电压比与匝数比，并分析实验中的误差来源。","mc":["能说明实验用低压交流电源和交流电压表的原因","能用控制变量法设计并处理实验数据","能分析实测电压比与匝数比偏差的原因"],"dq":{"q":"探究变压器原、副线圈电压与匝数的关系时，原线圈应该接在哪一种电源上？","a":"低压交流电源（不超过 12 V）"}},{"id":"cnp_h135","n":"电能的输送","g":"高5","sm":"上","ch":"选必二 第三章 交变电流 3.4","d":"远距离输电时，输送功率 P = UI。线路电阻 R 上的损耗 P损 = I²R，所以在功率一定时提高输电电压、减小电流，是减少输电损耗的有效办法；了解升压、降压变压器在输电过程中的作用。","mc":["会用 I = P/U 和 P损 = I²R 计算输电损耗","能说明采用高压输电的原因","知道输电线路中升、降压变压器的作用"],"dq":{"q":"发电站输出功率 P = 100 kW，用 U = 10 kV 的电压输电，输电线中的电流是多少 A？（只填数值）","a":"10"}},{"id":"cnp_h136","n":"发电机与电动机的能量转化","g":"高5","sm":"上","ch":"选必二 第三章 交变电流 3.4","d":"发电机把机械能转化为电能，电动机把电能转化为机械能和内能。电动机转动时线圈切割磁感线产生反电动势，对电路中的电流有阻碍作用；输入功率 UI 等于机械功率与线圈热功率 I²r 之和。","mc":["能说明发电机、电动机中的能量转化","知道反电动势的作用","会计算电动机的机械功率并分析堵转问题"],"dq":{"q":"发电机工作时的能量转化是哪一个？","a":"机械能转化为电能"}},{"id":"cnp_h137","n":"电磁振荡","g":"高5","sm":"上","ch":"选必二 第四章 电磁振荡与电磁波 4.1","d":"LC 回路中电容器反复充放电，电流和电荷量周期性变化，电场能与磁场能相互转化，总能量不变（忽略损耗）。振荡周期 T = 2π√(LC)，频率 f = 1/(2π√(LC))。","mc":["能分析 LC 回路充、放电过程中电流、电荷量和能量的变化","会用 T = 2π√(LC) 计算周期与频率","能判断 L、C 变化时周期的变化"],"dq":{"q":"LC 振荡电路中，电容器放电完毕（极板上电荷量为零）的瞬间，下列说法正确的是哪一个？","a":"电流最大，磁场能最大，电场能为零"}},{"id":"cnp_h138","n":"电磁场与电磁波","g":"高5","sm":"上","ch":"选必二 第四章 电磁振荡与电磁波 4.2","d":"麦克斯韦电磁场理论：变化的磁场产生电场，变化的电场产生磁场；均匀变化的场产生恒定的场，周期性变化的场产生同频率周期性变化的场。变化的电磁场向外传播形成电磁波，电磁波是横波，在真空中的速度 c 与频率无关。","mc":["能说出麦克斯韦电磁场理论的两个基本论点并判断场的类型","知道电磁波是横波，E、B、传播方向互相垂直","会用 c = λf 计算波长和频率"],"dq":{"q":"麦克斯韦电磁场理论的基本论点是哪一个？","a":"变化的磁场产生电场，变化的电场产生磁场"}},{"id":"cnp_h139","n":"无线电波的发射和接收","g":"高5","sm":"上","ch":"选必二 第四章 电磁振荡与电磁波 4.3","d":"无线电波的发射需要高频、开放的 LC 振荡电路，并用调制把声音等信号加在高频载波上（调幅改变振幅，调频改变频率）；接收时用调谐选出要接收的电台，再用解调（检波）把信号取出。","mc":["能说明有效发射电磁波的条件","能区分调制、调谐、解调","会用 f = 1/(2π√(LC)) 分析调谐电路中的 L、C 与频率的关系"],"dq":{"q":"要有效地向外发射电磁波，LC 振荡电路应满足哪个条件？","a":"振荡频率足够高，电路是开放的"}},{"id":"cnp_h140","n":"电磁波谱","g":"高5","sm":"上","ch":"选必二 第四章 电磁振荡与电磁波 4.4","d":"按波长由长到短，电磁波谱依次为无线电波、红外线、可见光、紫外线、X 射线、γ 射线；它们在真空中速度相同，频率越高波长越短。不同波段的电磁波特性不同，有各自的应用。","mc":["能按波长顺序说出电磁波谱","能把常见应用与对应波段匹配","会用 c = λf 在真空中换算波长和频率"],"dq":{"q":"下列电磁波按波长由长到短排列，顺序正确的是哪一个？","a":"无线电波、红外线、可见光、紫外线、X 射线、γ 射线"}},{"id":"cnp_h141","n":"认识传感器","g":"高5","sm":"上","ch":"选必二 第五章 传感器 5.1","d":"传感器是把力、热、光、声、位移等非电学量转换为便于测量和传输的电学量（如电压、电流、电阻、电容）的器件，一般由敏感元件、转换元件等组成。学习传感器的含义和类型。","mc":["能说明传感器的作用和基本组成","能把常见非电学量与对应的电学量联系起来","会用闭合电路规律分析简单的传感器电路"],"dq":{"q":"传感器的作用是哪一个？","a":"把非电学量转换为便于测量和传输的电学量"}},{"id":"cnp_h142","n":"常见传感器的工作原理及应用","g":"高5","sm":"上","ch":"选必二 第五章 传感器 5.2","d":"常见传感器：光敏电阻（光照越强阻值越小）、热敏电阻（NTC 随温度升高阻值减小）、金属热电阻（阻值随温度升高增大）、霍尔元件（磁感应强度转换为电压）、压力、声音和红外传感器等。了解它们的工作原理和应用。","mc":["能说出光敏电阻、热敏电阻的阻值变化规律","能说明霍尔元件把磁感应强度转换为电压的原理","能把常见传感器与实际应用对应起来"],"dq":{"q":"光敏电阻的阻值随光照强度变化的规律是哪一个？","a":"光照越强，阻值越小"}},{"id":"cnp_h143","n":"实验：利用传感器制作简单的自动控制装置","g":"高5","sm":"上","ch":"选必二 第五章 传感器 5.3","d":"利用光敏电阻或热敏电阻、电磁继电器和电源，组装光控或温控的自动控制装置，如天黑自动亮灯的路灯。学习传感器的接入方式、继电器的作用和调节灵敏度的方法。","mc":["能画出光控或温控自动控制装置的基本电路","知道电磁继电器用弱电控制强电","会通过调节电阻调整触发的阈值"],"dq":{"q":"在光控电路中，光敏电阻 RG 与定值电阻 R0 串联后接在恒压电源两端。天色变暗时，RG 的阻值变大，则 R0 两端的电压如何变化？","a":"减小"}},{"id":"cnp_h144","n":"分子动理论的基本内容","g":"高6","sm":"上","ch":"选必三 第一章 分子动理论 1.1","d":"分子动理论的基本内容：物质由大量分子组成，分子直径的数量级约为 10⁻¹⁰ m；阿伏伽德罗常数 N_A = 6.02×10²³ mol⁻¹；分子在永不停息地做无规则运动；分子间同时存在引力和斥力，在 r0 处二力相等。","mc":["知道分子大小的数量级和阿伏伽德罗常数","会用摩尔质量、N_A 计算分子数和分子体积","能说明分子力随分子间距离变化的规律"],"dq":{"q":"分子直径的数量级约为多少？","a":"10⁻¹⁰ m"}},{"id":"cnp_h145","n":"布朗运动与扩散","g":"高6","sm":"上","ch":"选必三 第一章 分子动理论 1.1","d":"布朗运动是悬浮在液体中的固体小颗粒的无规则运动，它不是分子本身的运动，而是液体分子无规则运动的反映；颗粒越小、温度越高，布朗运动越明显。扩散现象是不同物质彼此进入对方的现象，也说明分子在运动。","mc":["能说明布朗运动是什么、不是什么","能解释布朗运动的成因及影响因素","能区分布朗运动与扩散现象"],"dq":{"q":"布朗运动是指哪一个？","a":"悬浮在液体中的固体小颗粒的无规则运动"}},{"id":"cnp_h146","n":"实验：用油膜法估测油酸分子的大小","g":"高6","sm":"上","ch":"选必三 第一章 分子动理论 1.2","d":"油膜法估测分子直径：将油酸用酒精稀释，滴在撒有痱子粉的水面上形成单分子油膜，由一滴溶液中纯油酸的体积 V 和油膜面积 S，估算分子直径 d = V/S。学习体积换算、数格估算面积和误差分析。","mc":["能解释稀释油酸、撒痱子粉等操作的目的","会计算一滴溶液中纯油酸的体积和油膜面积","会用 d = V/S 估算分子直径并分析误差"],"dq":{"q":"用油膜法估测分子直径时，先把油酸用酒精稀释成油酸酒精溶液，目的是哪一个？","a":"便于形成单分子油膜，并能算出一滴溶液中纯油酸的体积"}},{"id":"cnp_h147","n":"分子运动速率分布规律","g":"高6","sm":"上","ch":"选必三 第一章 分子动理论 1.3","d":"大量气体分子的速率分布遵循统计规律：速率很大和很小的分子都很少，中等速率的分子最多（中间多、两头少）。温度升高时，速率分布曲线的峰值向速率大的方向移动，曲线变平坦，但并非每个分子的速率都增大。","mc":["能说出气体分子速率分布“中间多、两头少”","能比较不同温度下的速率分布曲线","能读懂分子速率分布的统计图并做简单计算"],"dq":{"q":"一定温度下，气体分子速率分布的规律是哪一个？","a":"速率很大和很小的分子都较少，中等速率的分子最多"}},{"id":"cnp_h148","n":"分子动能与温度","g":"高6","sm":"上","ch":"选必三 第一章 分子动理论 1.4","d":"分子热运动的平均动能是温度的标志：温度越高，分子热运动的平均动能越大。热力学温度 T = t + 273 K，平均动能与 T 成正比。温度对单个分子没有意义，同温度下不同气体分子平均动能相同、平均速率不同。","mc":["能说明温度是分子平均动能的标志","会区分平均动能、平均速率和总动能","会用热力学温度比较平均动能"],"dq":{"q":"关于温度与分子动能，下列说法正确的是哪一个？","a":"温度是分子热运动平均动能的标志"}},{"id":"cnp_h149","n":"分子势能与内能","g":"高6","sm":"上","ch":"选必三 第一章 分子动理论 1.4","d":"分子势能由分子间的相对位置决定。r > r0 时分子力表现为引力，r 增大则势能增大；r < r0 时表现为斥力，r 减小则势能增大；r = r0 时分子势能最小。物体的内能是所有分子的动能和势能之和。","mc":["能根据分子力做功判断分子势能变化","知道 r0 处分子势能最小","能分析状态变化时分子动能、势能和内能的变化"],"dq":{"q":"两个分子间距离 r 等于平衡距离 r0 时，下列说法正确的是哪一个？","a":"分子势能最小"}},{"id":"cnp_h150","n":"温度和温标","g":"高6","sm":"上","ch":"选必三 第二章 气体、固体和液体 2.1","d":"知道热平衡的含义和温度的意义：处于热平衡的系统温度相同。知道摄氏温标与热力学温标的关系 T = t + 273.15 K，两种温标下的温度变化量数值相等，绝对零度不能达到。","mc":["能在 T = t + 273.15 K 的基础上互相换算摄氏温度与热力学温度","知道 ΔT = Δt，温度差的数值与温标无关","知道热平衡时温度相同，而内能和热量不一定相同"],"dq":{"q":"把 27 ℃ 换算成热力学温度，应取（T = t + 273.15 K）","a":"300.15 K"}},{"id":"cnp_h151","n":"实验：探究等温情况下一定质量气体压强与体积的关系","g":"高6","sm":"上","ch":"选必三 第二章 气体、固体和液体 2.2","d":"用注射器和压强传感器封闭一段空气柱，缓慢改变体积并记录压强，探究温度不变时一定质量气体的压强与体积的关系，并通过作 p–1/V 图像检验猜想。","mc":["能说出保持气体质量和温度不变的操作要点","会作 p–1/V 图像并判断压强与体积是否成反比","能分析漏气、温度变化等造成的误差"],"dq":{"q":"探究等温情况下一定质量气体压强与体积的关系时，为了保持气体温度不变，下列操作正确的是","a":"缓慢推拉活塞，且手不要握住注射器封闭气体的部分"}},{"id":"cnp_h152","n":"气体的等温变化","g":"高6","sm":"上","ch":"选必三 第二章 气体、固体和液体 2.2","d":"知道一定质量的气体在温度不变时，压强与体积成反比，即玻意耳定律 p1V1 = p2V2；能用它解决汽缸、液柱管等等温变化问题，并理解 p–V 图像上的等温线。","mc":["能判断玻意耳定律的适用条件（质量一定、温度不变）","会用 p1V1 = p2V2 计算压强或体积，注意两边单位一致","能由 p–V 图上的等温线比较温度高低"],"dq":{"q":"一定质量的气体做等温压缩，体积由 6.0 L 变为 2.0 L，压强原来为 1.0 atm，则压缩后压强为","a":"3.0 atm"}},{"id":"cnp_h153","n":"气体的等压变化和等容变化","g":"高6","sm":"上","ch":"选必三 第二章 气体、固体和液体 2.3","d":"知道一定质量气体等压变化时体积与热力学温度成正比（盖—吕萨克定律），等容变化时压强与热力学温度成正比（查理定律）；使用时必须把温度换成热力学温度。","mc":["能用 V1/T1 = V2/T2 和 p1/T1 = p2/T2 计算，并把摄氏温度换成热力学温度","能说出 V–t、p–t 图线为直线且延长线交 t 轴于 −273.15 ℃","能判断两部分气体升温时液柱的移动方向"],"dq":{"q":"一定质量的气体在压强不变时，温度由 27 ℃ 升高到 127 ℃，体积变为原来的多少倍？（热力学温度取 T = t + 273 K）","a":"4/3 倍"}},{"id":"cnp_h154","n":"理想气体状态方程","g":"高6","sm":"上","ch":"选必三 第二章 气体、固体和液体 2.3","d":"知道理想气体是严格遵守气体实验定律的理想模型；掌握理想气体状态方程 pV/T = C（T 为热力学温度），能处理三个状态参量同时变化的问题。","mc":["能说出理想气体模型及实际气体可视为理想气体的条件","会用 p1V1/T1 = p2V2/T2 解决状态变化问题","能由 p–V 图上两状态的 pV 乘积判断温度变化"],"dq":{"q":"关于理想气体，下列说法正确的是","a":"理想气体是严格遵守气体实验定律的气体模型"}},{"id":"cnp_h155","n":"气体压强的微观解释","g":"高6","sm":"上","ch":"选必三 第二章 气体、固体和液体 2.3","d":"知道气体压强是大量气体分子频繁碰撞器壁产生的，其大小取决于分子的平均动能和分子数密度；能用分子动理论和统计观点解释玻意耳、查理、盖—吕萨克定律。","mc":["能说明气体压强的微观成因，知道它与重力无关","能用分子数密度和平均动能解释等温、等容、等压变化中压强的变化","能判断体积和温度同时变化时压强的变化趋势"],"dq":{"q":"在绕地球运行、处于完全失重状态的空间站里，密闭容器中的气体对器壁","a":"仍有压强，压强由大量分子对器壁的频繁碰撞产生，与重力无关"}},{"id":"cnp_h156","n":"固体","g":"高6","sm":"上","ch":"选必三 第二章 气体、固体和液体 2.4","d":"知道晶体（单晶体、多晶体）与非晶体的区别：晶体有确定熔点，单晶体某些物理性质各向异性，多晶体和非晶体各向同性；晶体内部粒子按规则排列。","mc":["能区分常见的晶体和非晶体","能说明单晶体、多晶体、非晶体在外形、熔点、各向异性上的区别","能由熔化曲线判断晶体并分析熔化时的能量变化"],"dq":{"q":"下列物质中属于晶体的是","a":"食盐"}},{"id":"cnp_h157","n":"液体","g":"高6","sm":"上","ch":"选必三 第二章 气体、固体和液体 2.5","d":"了解液体表面张力的产生原因，知道浸润与不浸润、毛细现象的微观解释，了解液晶既有液体的流动性又有晶体的各向异性，及其在显示技术中的应用。","mc":["能解释表面张力使液面收缩的原因","能区分浸润与不浸润并判断毛细管内液面升降","知道液晶的主要性质"],"dq":{"q":"液体表面张力产生的原因是","a":"液体表面层的分子间距比内部大，分子间作用力表现为引力"}},{"id":"cnp_h158","n":"功、热和内能的改变","g":"高6","sm":"上","ch":"选必三 第三章 热力学定律 3.1","d":"知道做功和热传递都能改变系统的内能，二者对改变内能是等效的，但本质不同；知道焦耳实验说明绝热过程中外界对系统做的功等于系统内能的增量，内能是状态量。","mc":["能区分做功和热传递改变内能的本质","能由焦耳实验的装置计算绝热过程中的内能增量","知道内能的变化只与初末状态有关，与过程无关"],"dq":{"q":"做功和热传递都能改变物体的内能，二者的本质区别是","a":"做功是其他形式的能与内能之间的转化，热传递是内能的转移"}},{"id":"cnp_h159","n":"热力学第一定律","g":"高6","sm":"上","ch":"选必三 第三章 热力学定律 3.2","d":"掌握热力学第一定律 ΔU = W + Q：一个热力学系统的内能增量等于外界向它传递的热量与外界对它所做的功之和。会按符号约定代入并求解。","mc":["能说出 W、Q、ΔU 的正负含义","能用 ΔU = W + Q 计算内能变化，并判断气体膨胀时 W 为负","能判断绝热等特殊过程中内能的变化"],"dq":{"q":"一定质量的气体从外界吸收热量 500 J，同时气体膨胀对外界做功 200 J，则气体内能的变化量 ΔU（增加为正）为","a":"300 J"}},{"id":"cnp_h160","n":"热力学第一定律与气体状态变化的综合","g":"高6","sm":"上","ch":"选必三 第三章 热力学定律 3.2","d":"把热力学第一定律与气体状态变化结合：理想气体内能只与温度有关，等温 ΔU = 0，等容 W = 0，绝热 Q = 0；等压膨胀时 W = −pΔV；会判断吸放热和做功情况。","mc":["能说出理想气体内能只取决于温度","能分别分析等温、等容、等压、绝热过程中的 W、Q、ΔU","能计算等压过程中气体对外做的功 pΔV"],"dq":{"q":"一定质量的理想气体等温膨胀，对外界做功 W′，则气体","a":"从外界吸收热量，吸收的热量等于对外界做的功"}},{"id":"cnp_h161","n":"能量守恒定律","g":"高6","sm":"上","ch":"选必三 第三章 热力学定律 3.3","d":"理解能量守恒定律：能量既不会凭空产生，也不会凭空消失，只能从一种形式转化为另一种形式，或从一个物体转移到别的物体，总量不变；知道第一类永动机不可能制成。","mc":["能陈述能量守恒定律并用它分析机械能减少等现象","能计算能量转化中产生的内能","知道第一类永动机违背能量守恒定律，以及能量守恒仍要节约能源的原因"],"dq":{"q":"关于能量守恒定律，下列说法正确的是","a":"能量可以从一种形式转化为另一种形式，也可以从一个物体转移到别的物体，总量不变"}},{"id":"cnp_h162","n":"热力学第二定律","g":"高6","sm":"上","ch":"选必三 第三章 热力学定律 3.4","d":"知道热力学第二定律的克劳修斯表述和开尔文表述，知道第二类永动机不可能制成；知道自发过程具有方向性，孤立系统的自发过程总是向熵增加（无序程度增大）的方向进行。","mc":["能说出两种表述并区分“自发”的含义","能解释冰箱等不违背第二定律","能用熵增加原理判断自发过程的方向"],"dq":{"q":"热力学第二定律的克劳修斯表述是","a":"热量不能自发地从低温物体传到高温物体"}},{"id":"cnp_h163","n":"黑体辐射与能量子","g":"高6","sm":"上","ch":"选必三 第四章 原子结构和波粒二象性 4.1","d":"了解黑体与黑体辐射的实验规律：温度升高时各种波长的辐射强度都增加，辐射强度的极大值向波长较短的方向移动。知道普朗克的能量子假说，辐射或吸收的能量只能是 ε = hν 的整数倍，理解能量子是微观世界量子化特征的开端。","mc":["能说出黑体辐射的实验规律","能说出能量子假说的内容","会用 ε = hν 计算一个能量子的能量"],"dq":{"q":"普朗克为解释黑体辐射的实验规律，提出了能量子假说。下列对这一假说的表述正确的是哪一个？","a":"能量只能是最小能量值 ε = hν 的整数倍，是一份一份地辐射或吸收"}},{"id":"cnp_h164","n":"光电效应现象","g":"高6","sm":"上","ch":"选必三 第四章 原子结构和波粒二象性 4.2","d":"通过实验了解光电效应现象：光照射金属时有电子逸出；存在截止频率，低于截止频率无论光多强、照射多久都不能发生；光电子最大初动能与光强无关；饱和光电流随光强增大；发生过程几乎是瞬时的。","mc":["能说出光电效应的四条实验规律","能区分光强与光频率各自的作用","会利用饱和光电流估算单位时间逸出的光电子数"],"dq":{"q":"用某单色光照射金属表面时，没有光电子逸出。下列做法中，可能使金属发生光电效应的是哪一个？","a":"换用频率更高的光照射"}},{"id":"cnp_h165","n":"爱因斯坦光电效应方程","g":"高6","sm":"上","ch":"选必三 第四章 原子结构和波粒二象性 4.2","d":"掌握爱因斯坦光电效应方程 Ek = hν − W0：一个光子的能量一次性被一个电子吸收，一部分用来克服逸出功，其余成为光电子的最大初动能；遏止电压满足 Uc·e = Ek；能分析 Ek−ν 图像的斜率与截距。","mc":["会用 Ek = hν − W0 计算最大初动能与截止频率（截止波长）","会由 Uc·e = Ek 求遏止电压","能从 Ek−ν 图像读出 h、W0 和截止频率"],"dq":{"q":"某金属的逸出功为 2.3 eV，用光子能量为 4.1 eV 的光照射它，逸出光电子的最大初动能是多少 eV？（只填数值）","a":"1.8"}},{"id":"cnp_h166","n":"原子的核式结构模型","g":"高6","sm":"上","ch":"选必三 第四章 原子结构和波粒二象性 4.3","d":"了解 α 粒子散射实验的装置和现象：绝大多数 α 粒子几乎沿原方向穿过金箔，少数发生大角度偏转，极少数偏转角超过 90°。由此得出原子的核式结构模型：原子中心有一个很小的核，集中了全部正电荷和几乎全部质量。","mc":["能说出 α 粒子散射实验的现象","能说出核式结构模型的内容","能用库仑力解释大角度偏转并估算最近距离"],"dq":{"q":"在 α 粒子散射实验中，让 α 粒子轰击很薄的金箔，观察到的现象是哪一个？","a":"绝大多数 α 粒子几乎沿原方向穿过，少数发生大角度偏转，极少数被反弹回来"}},{"id":"cnp_h167","n":"氢原子光谱","g":"高6","sm":"上","ch":"选必三 第四章 原子结构和波粒二象性 4.4","d":"知道氢原子光谱是由一些分立的亮线组成的线状谱，不同原子的特征谱线不同，可用来进行光谱分析；了解巴耳末公式 1/λ = R(1/2² − 1/n²)（n = 3, 4, 5, …），并知道经典电磁理论无法解释原子光谱的分立特征。","mc":["能区分连续谱与线状谱","会用巴耳末公式比较谱线波长","知道光谱分析的原理"],"dq":{"q":"稀薄氢气放电发光，经棱镜或光栅分光后得到的氢原子光谱是哪一个？","a":"由若干条分立的亮线组成的线状谱"}},{"id":"cnp_h168","n":"玻尔的原子模型与能级","g":"高6","sm":"上","ch":"选必三 第四章 原子结构和波粒二象性 4.4","d":"知道玻尔模型：原子只能处于一系列不连续的能量状态（定态），氢原子能级 E_n = −13.6 eV/n²；原子在能级间跃迁时辐射或吸收光子，hν = E_m − E_n；一群处于 n 能级的氢原子最多可辐射 n(n−1)/2 种频率的光。","mc":["会由能级公式计算跃迁时光子的能量","会计算一群氢原子跃迁的谱线数","能分析跃迁时动能、势能和总能量的变化"],"dq":{"q":"氢原子的能级公式为 E_n = −13.6 eV/n²。氢原子从 n = 2 的能级跃迁到 n = 1 的能级时，辐射的光子能量是多少 eV？（只填数值）","a":"10.2"}},{"id":"cnp_h169","n":"粒子的波动性和波粒二象性","g":"高6","sm":"上","ch":"选必三 第四章 原子结构和波粒二象性 4.5","d":"知道光既具有波动性（干涉、衍射）又具有粒子性（光电效应），即波粒二象性；知道实物粒子也具有波动性，德布罗意波长 λ = h/p，电子衍射实验证实了这一点；了解大量粒子与个别粒子表现的差异。","mc":["能说明光的波粒二象性","会用 λ = h/p 计算德布罗意波长","知道电子衍射证明实物粒子具有波动性"],"dq":{"q":"质量不同的电子和质子以相同的速度运动，它们的德布罗意波长相比，下列说法正确的是哪一个？","a":"电子的德布罗意波长较长"}},{"id":"cnp_h170","n":"天然放射现象与射线","g":"高6","sm":"上","ch":"选必三 第五章 原子核 5.1","d":"知道贝可勒尔发现天然放射现象，说明原子核有复杂的内部结构；知道 α、β、γ 射线的本质（氦核流、电子流、波长极短的电磁波）、在磁场中的偏转情况，以及电离本领与穿透本领的强弱关系。","mc":["能说出三种射线的本质","能比较三种射线的电离本领和穿透本领","能判断射线在磁场中的偏转方向"],"dq":{"q":"天然放射性元素放出的 β 射线的本质是哪一个？","a":"高速电子流"}},{"id":"cnp_h171","n":"原子核的组成","g":"高6","sm":"上","ch":"选必三 第五章 原子核 5.1","d":"知道原子核由质子和中子（统称核子）组成；质量数 A 等于核子数，电荷数 Z 等于质子数，中子数为 A − Z；知道同位素是质子数相同而中子数不同的原子，化学性质几乎相同。","mc":["会用 ᴬ_Z X 符号表示原子核并求质子数、中子数","能判断哪些原子核互为同位素","知道质量数、电荷数的含义"],"dq":{"q":"铀核 ²³⁸₉₂U 的质量数为 238，电荷数为 92，它的原子核内含有多少个中子？（只填数值）","a":"146"}},{"id":"cnp_h172","n":"原子核的衰变","g":"高6","sm":"上","ch":"选必三 第五章 原子核 5.2","d":"知道原子核自发地放出 α 粒子或 β 粒子而变成新核的过程叫衰变；会按质量数守恒和电荷数守恒写出 α 衰变、β 衰变的核反应方程，并计算衰变次数；知道 β 衰变中的电子来自核内中子转化为质子。","mc":["能写出 α 衰变和 β 衰变的核反应方程","会计算衰变次数","能用动量守恒分析静止原子核衰变后的反冲"],"dq":{"q":"²³⁸₉₂U 发生一次 α 衰变后，产生的新核是哪一个？","a":"²³⁴₉₀Th"}},{"id":"cnp_h173","n":"半衰期","g":"高6","sm":"上","ch":"选必三 第五章 原子核 5.2","d":"知道半衰期是大量放射性原子核有半数发生衰变所需的时间，剩余量 N = N₀(½)^(t/τ)；半衰期由原子核自身性质决定，与温度、压强及化学状态无关；半衰期是统计规律，对少量原子核没有意义。","mc":["会用 N = N₀(½)^(t/τ) 计算剩余量","知道半衰期与外界条件无关","能说明半衰期的统计意义"],"dq":{"q":"某放射性元素的半衰期为 5 天，现有 80 g 该元素，经过 15 天后还剩下多少 g 尚未衰变？（只填数值）","a":"10"}},{"id":"cnp_h174","n":"放射性同位素及其应用与防护","g":"高6","sm":"上","ch":"选必三 第五章 原子核 5.2","d":"了解放射性同位素的应用：利用 γ 射线探伤、治疗，利用射线的穿透能力测厚，作示踪原子，以及用于育种、保鲜；知道射线对人体有伤害，防护要靠缩短接触时间、增大距离和屏蔽，并了解人工放射性同位素的获得。","mc":["能说出放射性同位素的主要应用","知道示踪原子的原理","知道射线防护的基本措施"],"dq":{"q":"工业上利用射线检查金属内部有无裂缝（探伤），应选用的射线是哪一个？","a":"γ 射线"}},{"id":"cnp_h175","n":"核力与结合能","g":"高6","sm":"上","ch":"选必三 第五章 原子核 5.3","d":"知道核力是短程的强相互作用力，只在约 10⁻¹⁵ m 的范围内起作用；核子结合成原子核时放出的能量叫结合能，质量亏损 Δm 与释放能量的关系为 ΔE = Δmc²，1 u 对应 931.5 MeV；比结合能越大，原子核越稳定。","mc":["能说出核力的主要性质","会用 ΔE = Δmc² 计算结合能","会用比结合能判断原子核的稳定性"],"dq":{"q":"关于核力，下列说法正确的是哪一个？","a":"核力是短程力，只在约 10⁻¹⁵ m 的距离内起作用"}},{"id":"cnp_h176","n":"核裂变与核聚变","g":"高6","sm":"上","ch":"选必三 第五章 原子核 5.4","d":"知道重核裂变（如铀 235 吸收中子后裂变并放出中子）、链式反应与临界体积，知道核反应堆的基本原理；知道轻核聚变的方程和条件（极高温度以克服库仑斥力），并能估算核反应释放的能量。","mc":["能区分裂变、聚变、衰变和人工转变方程","能说出链式反应的条件","能估算裂变释放的能量"],"dq":{"q":"下列核反应方程中，属于重核裂变的是哪一个？","a":"²³⁵₉₂U + ¹₀n → ¹⁴⁴₅₆Ba + ⁸⁹₃₆Kr + 3¹₀n"}},{"id":"cnp_h177","n":"基本粒子与四种基本相互作用","g":"高6","sm":"上","ch":"选必三 第五章 原子核 5.5","d":"知道自然界有四种基本相互作用：引力、电磁相互作用、强相互作用和弱相互作用；了解粒子分为强子、轻子和规范玻色子，强子由夸克组成，夸克带分数电荷；体会人类对物质结构不断深入探索的过程。","mc":["能说出四种基本相互作用及各自的作用","能对常见粒子进行分类","会根据夸克电荷计算粒子的电荷"],"dq":{"q":"把原子核中的核子束缚在一起、维持原子核稳定的相互作用是哪一个？","a":"强相互作用"}}];
